(2, 'tk_lr', 'Marketing', 'Jetpack - Stores the unique identifier for the publisher to enable Jetpack to collect data.', 'eyeshottourism.com', '/', '2026-12-25 13:33:19', NULL, NULL, 0, 0, 'tk_lr', 1, '[]', 1766669631),
(3, 'sbjs_first_add', 'Analytics', 'Timestamp, referring URL, and entry page for your visitor’s first visit to your store (only applicable if the visitor returns before the session expires)', '.eyeshottourism.com', '/', NULL, NULL, NULL, 0, 0, 'sbjs_first_add', 1, '[]', 1766669631),
(4, 'tk_r3d', 'Analytics', 'JetPack installs this cookie to collect internal metrics for user activity and in turn improve user experience.', 'eyeshottourism.com', '/', '2025-12-28 13:33:19', NULL, NULL, 0, 0, 'tk_r3d', 1, '[]', 1766669631),
(5, 'sbjs_session', 'Analytics', 'The number of page views in this session and the current page path', '.eyeshottourism.com', '/', '2025-12-25 14:03:18', NULL, NULL, 0, 0, 'sbjs_session', 1, '[]', 1766669631),
