INSERT INTO `wp1l_options` (`option_id`, `option_name`, `option_value`, `autoload`) VALUES
(9372, 'wp_travel_engine_settings', 'a:125:{s:5:\"pages\";a:8:{s:7:\"enquiry\";i:212;s:26:\"wp_travel_engine_thank_you\";s:3:\"213\";s:28:\"wp_travel_engine_place_order\";s:3:\"214\";s:37:\"wp_travel_engine_terms_and_conditions\";s:3:\"215\";s:34:\"wp_travel_engine_confirmation_page\";s:3:\"216\";s:31:\"wp_travel_engine_dashboard_page\";s:3:\"217\";s:25:\"wp_travel_engine_wishlist\";s:3:\"207\";s:6:\"search\";s:3:\"208\";}s:24:\"display_new_trip_listing\";s:3:\"yes\";s:13:\"currency_code\";s:3:\"USD\";s:15:\"currency_option\";s:6:\"symbol\";s:19:\"thousands_separator\";s:0:\"\";s:5:\"email\";a:20:{s:13:\"disable_notif\";s:0:\"\";s:6:\"emails\";s:50:\"tours@eyeshottourism.com, haris@eyeshottourism.com\";s:10:\"cust_notif\";s:1:\"1\";s:4:\"from\";s:24:\"tours@eyeshottourism.com\";s:34:\"booking_notification_subject_admin\";s:54:\"New Trip is Booked - {booked_trip_name} - {booking_id}\";s:35:\"booking_notification_template_admin\";s:933:\"	<table style=\"width:100%;\">\n		<tr>\n			<td colspan=\"2\" style=\"font-size: 24px;line-height: 1.5;font-weight: bold;\">\n				Your Trip is Booked.			</td>\n		</tr>\n		<tr>\n			<td colspan=\"2\" style=\"padding: 16px 0 8px;\">\n			<strong>Dear Admin,</strong>\n			<p style=\"margin: 8px 0 0;\">Your trip <strong>{booked_trip_name}</strong> is booked by <strong>{customer_full_name}</strong> on <strong>{trip_booked_date}</strong>.<br>Here\'s the booked trip details:</p>\n			</td>\n		</tr>\n		<tr>\n			<td colspan=\"2\">\n				{trip_booking_details}\n			</td>\n		</tr>\n		<tr>\n			<td colspan=\"2\" style=\"padding: 16px 0;\">\n				<a target=\"_blank\" style=\"display: block;font-size: 16px;line-height: 1;font-weight: 600;color: #fff;padding: 20px;background-color: #000;border-radius: 50px;text-align: center;text-decoration: none;\" href=\"{booking_url}\">VIEW DETAILS</a>\n			</td>\n		</tr>\n		<tr>\n			<td colspan=\"2\">\n				Regards, <br>{sitename}			</td>\n		</tr>\n	</table>\n\";s:28:\"disable_booking_notification\";N;s:12:\"sale_subject\";s:42:\"Payment has been received for {booking_id}\";s:14:\"sales_wpeditor\";s:981:\"	<table style=\"width:100%;\">\n		<tr>\n			<td colspan=\"2\" style=\"font-size: 24px;line-height: 1.5;font-weight: bold;\">\n				New Payment Received.			</td>\n		</tr>\n		<tr>\n			<td colspan=\"2\" style=\"padding: 16px 0 8px;\">\n			<strong>Dear Admin,</strong>\n			<p style=\"margin: 8px 0 0;\">The payment for the trip <strong>{booked_trip_name}</strong>, booked by <strong>{customer_full_name}</strong> on <strong>{trip_booked_date}</strong>, has been successfully received.<br>Here are the booked trip details:</p>\n			</td>\n		</tr>\n		<tr>\n			<td colspan=\"2\">\n				{trip_payment_details}\n			</td>\n		</tr>\n		<tr>\n			<td colspan=\"2\" style=\"padding: 16px 0;\">\n				<a target=\"_blank\" style=\"display: block;font-size: 16px;line-height: 1;font-weight: 600;color: #fff;padding: 20px;background-color: #000;border-radius: 50px;text-align: center;text-decoration: none;\" href=\"{booking_url}\">VIEW DETAILS</a>\n			</td>\n		</tr>\n		<tr>\n			<td colspan=\"2\">\n				Regards, <br>{sitename}			</td>\n		</tr>\n	</table>\n\";s:37:\"booking_notification_subject_customer\";s:65:\"Your booking for {booked_trip_name} is confirmed – {booking_id}\";s:38:\"booking_notification_template_customer\";s:1152:\"	<table style=\"width:100%;\">\n		<tr>\n			<td colspan=\"2\" style=\"font-size: 24px;line-height: 1.5;font-weight: bold;\">\n				Your Trip is Booked.			</td>\n		</tr>\n		<tr>\n			<td colspan=\"2\" style=\"padding: 16px 0 8px;\">\n			<strong>Dear {customer_first_name},</strong>\n			<p style=\"margin: 8px 0 0;\">Thank you for booking <strong>{booked_trip_name}</strong> with us! <br> Your trip has been successfully booked on <strong>{trip_booked_date}</strong> which starts on <strong>{trip_start_date}</strong>.<br> We\'re excited to have you on board.<br>Here\'s a quick summary of your booking:</p>\n			</td>\n		</tr>\n		<tr>\n			<td colspan=\"2\">\n				{trip_booking_details}\n			</td>\n		</tr>\n	