(2281, 332, '_elementor_data', '[{\"id\":\"ac330c6\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":133.482},\"min_height\":{\"unit\":\"px\",\"size\":0,\"sizes\":[]},\"_flex_size\":\"none\",\"_element_width\":\"initial\"},\"elements\":[{\"id\":\"506ec4fb\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<!-- wp:group {\\\"metadata\\\":{\\\"name\\\":\\\"Tour Experience Highlights\\\"},\\\"align\\\":\\\"full\\\",\\\"style\\\":{\\\"spacing\\\":{\\\"padding\\\":{\\\"top\\\":\\\"var:preset|spacing|60\\\",\\\"right\\\":\\\"var:preset|spacing|30\\\",\\\"bottom\\\":\\\"var:preset|spacing|60\\\",\\\"left\\\":\\\"var:preset|spacing|30\\\"},\\\"blockGap\\\":\\\"var:preset|spacing|60\\\",\\\"margin\\\":{\\\"top\\\":\\\"0\\\",\\\"bottom\\\":\\\"0\\\"}}},\\\"backgroundColor\\\":\\\"background\\\",\\\"layout\\\":{\\\"inherit\\\":true,\\\"type\\\":\\\"constrained\\\"}} -->\\n<div class=\\\"wp-block-group alignfull has-background-background-color has-background\\\" style=\\\"margin-top: 0; margin-bottom: 0; padding: var(--wp--preset--spacing--60) var(--wp--preset--spacing--30) var(--wp--preset--spacing--60) var(--wp--preset--spacing--30);\\\"><!-- wp:columns {\\\"align\\\":\\\"wide\\\",\\\"style\\\":{\\\"spacing\\\":{\\\"blockGap\\\":{\\\"top\\\":\\\"var:preset|spacing|40\\\",\\\"left\\\":\\\"var:preset|spacing|40\\\"}}}} -->\\n<div class=\\\"wp-block-columns alignwide\\\"><!-- wp:column -->\\n<div class=\\\"wp-block-column\\\"><!-- wp:group {\\\"align\\\":\\\"wide\\\",\\\"layout\\\":{\\\"type\\\":\\\"constrained\\\",\\\"justifyContent\\\":\\\"center\\\",\\\"contentSize\\\":\\\"\\\"}} -->\\n<div class=\\\"wp-block-group alignwide\\\"><!-- wp:heading {\\\"fontSize\\\":\\\"large\\\"} -->\\n<h2 class=\\\"wp-block-heading has-large-font-size\\\">Service Overview<\\/h2>\\n<!-- \\/wp:heading --><!-- wp:paragraph {\\\"style\\\":{\\\"spacing\\\":{\\\"margin\\\":{\\\"top\\\":\\\"16px\\\"}}}} -->\\n<p style=\\\"margin-top: 16px;\\\">Discover the unique elements of our personalized tours, crafted to immerse you in Qatar\\u2019s rich culture, history, and modern marvels, ensuring a memorable journey.<\\/p>\\n<!-- \\/wp:paragraph --><!-- wp:buttons {\\\"style\\\":{\\\"spacing\\\":{\\\"margin\\\":{\\\"top\\\":\\\"var:preset|spacing|30\\\"}}},\\\"layout\\\":{\\\"type\\\":\\\"flex\\\"}} -->\\n<div class=\\\"wp-block-buttons\\\" style=\\\"margin-top: var(--wp--preset--spacing--30);\\\"><!-- wp:button {\\\"className\\\":\\\"is-style-fill\\\"} -->\\n<div class=\\\"wp-block-button is-style-fill\\\"><a class=\\\"wp-block-button__link wp-element-button\\\" href=\\\"https:\\/\\/eyeshottourism.com\\/contact\\\">Discover Tours<\\/a><\\/div>\\n<!-- \\/wp:button --><\\/div>\\n<!-- \\/wp:buttons --><\\/div>\\n<!-- \\/wp:group --><\\/div>\\n<!-- \\/wp:column --><!-- wp:column -->\\n<div class=\\\"wp-block-column\\\"><!-- wp:group {\\\"style\\\":{\\\"spacing\\\":{\\\"blockGap\\\":\\\"1.25rem\\\"}},\\\"layout\\\":{\\\"type\\\":\\\"flex\\\",\\\"flexWrap\\\":\\\"nowrap\\\",\\\"verticalAlignment\\\":\\\"top\\\"}} -->\\n<div class=\\\"wp-block-group\\\"><!-- wp:image {\\\"scale\\\":\\\"cover\\\",\\\"sizeSlug\\\":\\\"large\\\",\\\"className\\\":\\\"ext-aspect-landscape extendify-image-import\\\",\\\"style\\\":{\\\"color\\\":{\\\"duotone\\\":\\\"var:preset|duotone|primary-foreground\\\"}}} -->\\n<figure class=\\\"wp-block-image size-large ext-aspect-landscape extendify-image-import\\\"><img style=\\\"object-fit: cover;\\\" src=\\\"data:image\\/svg+xml;base64,\\\" alt=\\\"\\\" \\/><\\/figure>\\n<!-- \\/wp:image --><!-- wp:group {\\\"style\\\":{\\\"layout\\\":{\\\"selfStretch\\\":\\\"fixed\\\",\\\"flexSize\\\":\\\"100%\\\"}},\\\"layout\\\":{\\\"type\\\":\\\"constrained\\\"}} -->\\n<div class=\\\"wp-block-group\\\"><!-- wp:heading {\\\"level\\\":3,\\\"style\\\":{\\\"typography\\\":{\\\"fontSize\\\":\\\"20px\\\",\\\"lineHeight\\\":\\\"1.5\\\"}}} -->\\n<h3 class=\\\"wp-block-heading\\\" style=\\\"font-size: 20px; line-height: 1.5;