(34, 1, '2025-11-13 13:27:12', '2025-11-13 13:27:12', '<!-- wp:group {\"align\":\"full\",\"backgroundColor\":\"background\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"right\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|30\"},\"blockGap\":\"var:preset|spacing|40\",\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"},\"metadata\":{\"name\":\" Testimonial\"}} -->\n<div class=\"wp-block-group alignfull has-background-background-color has-background\" id=\"testimonials\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--60);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:group {\"align\":\"wide\",\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"center\",\"contentSize\":\"\"}} -->\n<div class=\"wp-block-group alignwide\"><!-- wp:heading {\"textAlign\":\"center\",\"fontSize\":\"large\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-large-font-size\">Personalized Journeys Through Qatar\'s Rich Heritage</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<p class=\"has-text-align-center\" style=\"margin-top:16px\">Hear from our delighted travelers about their unforgettable cultural and historical tours with Eyeshot Tourism.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"align\":\"wide\"} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"verticalAlignment\":\"stretch\"} -->\n<div class=\"wp-block-column is-vertically-aligned-stretch\"><!-- wp:group {\"backgroundColor\":\"tertiary\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":\"4px\"},\"dimensions\":{\"minHeight\":\"100%\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-tertiary-background-color has-background\" style=\"border-radius:4px;min-height:100%;padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:image {\"sizeSlug\":\"large\",\"className\":\"extendify-image-import\",\"style\":{\"color\":{\"duotone\":\"var:preset|duotone|primary-foreground\"}}} -->\n<figure class=\"wp-block-image size-large extendify-image-import\"><img src=\"data:image/svg+xml;base64,\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\"},\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|20\"}}}} -->\n<p style=\"margin-top:var(--wp--preset--spacing--20);font-style:normal;font-weight:500\">\"Eyeshot Tourism crafted an exceptional itinerary that perfectly captured the spirit of Qatar. Every detail was thoughtfully planned.\"</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"1rem\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:image {\"aspectRatio\":\"1\",\"scale\":\"cover\",\"align\":\"center\",\"className\":\"is-style-rounded extendify-image-import\"} -->\n<figure class=\"wp-block-image aligncenter is-style-rounded extendify-image-import\"><img src=\"https://images.unsplash.com/photo-1614204424926-196a80bf0be8?fit=crop&amp;crop=entropy%2Cfaces&amp;auto=format%2Ccompress&amp;w=64&amp;h=64\" alt=\"\" style=\"aspect-ratio:1;object-fit:cover\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"level\":4,\"fontSize\":\"small\"} -->\n<h4 class=\"wp-block-heading has-small-font-size\">Fatima Al-Mansoori</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"fontSize\":\"small\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"2px\"}}}} -->\n<p class=\"has-small-font-size\" style=\"margin-top:2px\">Cultural Enthusiast and Blogger</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"stretch\"} -->\n<div class=\"wp-block-column is-vertically-aligned-stretch\"><!-- wp:group {\"backgroundColor\":\"tertiary\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":\"4px\"},\"dimensions\":{\"minHeight\":\"100%\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-tertiary-background-color has-background\" style=\"border-radius:4px;min-height:100%;padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:image {\"sizeSlug\":\"large\",\"className\":\"extendify-image-import\",\"style\":{\"color\":{\"duotone\":\"var:preset|duotone|primary-foreground\"}}} -->\n<figure class=\"wp-block-image size-large extendify-image-import\"><img src=\"data:image/svg+xml;base64,\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\"},\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|20\"}}}} -->\n<p style=\"margin-top:var(--wp--preset--spacing--20);font-style:normal;font-weight:500\">\"The team\'s professionalism and deep knowledge made our journey immersive and seamless, exceeding all expectations.\"</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"1rem\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:image {\"aspectRatio\":\"1\",\"scale\":\"cover\",\"align\":\"center\",\"className\":\"is-style-rounded extendify-image-import\"} -->\n<figure class=\"wp-block-image aligncenter is-style-rounded extendify-image-import\"><img src=\"https://images.unsplash.com/photo-1593757147298-e064ed1419e5?fit=crop&amp;crop=entropy%2Cfaces&amp;auto=format%2Ccompress&amp;w=64&amp;h=64\" alt=\"\" style=\"aspect-ratio:1;object-fit:cover\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"level\":4,\"fontSize\":\"small\"} -->\n<h4 class=\"wp-block-heading has-small-font-size\">Omar Khalid</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"fontSize\":\"small\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"2px\"}}}} -->\n<p class=\"has-small-font-size\" style=\"margin-top:2px\">History Professor</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"stretch\"} -->\n<div class=\"wp-block-column is-vertically-aligned-stretch\"><!-- wp:group {\"backgroundColor\":\"tertiary\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":\"4px\"},\"dimensions\":{\"minHeight\":\"100%\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-tertiary-background-color has-background\" style=\"border-radius:4px;min-height:100%;padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:image {\"sizeSlug\":\"large\",\"className\":\"extendify-image-import\",\"style\":{\"color\":{\"duotone\":\"var:preset|duotone|primary-foreground\"}}} -->\n<figure class=\"wp-block-image size-large extendify-image-import\"><img src=\"data:image/svg+xml;base64,\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\"},\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|20\"}}}} -->\n<p style=\"margin-top:var(--wp--preset--spacing--20);font-style:normal;font-weight:500\">\"From the vibrant souks to modern landmarks, every moment was perfectly curated. Truly a five-star experience.\"</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"1rem\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:image {\"aspectRatio\":\"1\",\"scale\":\"cover\",\"align\":\"center\",\"className\":\"is-style-rounded extendify-image-import\"} -->\n<figure class=\"wp-block-image aligncenter is-style-rounded extendify-image-import\"><img src=\"https://images.unsplash.com/photo-1525134479668-1bee5c7c6845?fit=crop&amp;crop=entropy%2Cfaces&amp;auto=format%2Ccompress&amp;w=64&amp;h=64\" alt=\"\" style=\"aspect-ratio:1;object-fit:cover\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"level\":4,\"fontSize\":\"small\"} -->\n<h4 class=\"wp-block-heading has-small-font-size\">Laila Hassan</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"fontSize\":\"small\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"2px\"}}}} -->\n<p class=\"has-small-font-size\" style=\"margin-top:2px\">Travel Writer</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"backgroundColor\":\"tertiary\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"right\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|30\"},\"blockGap\":\"var:preset|spacing|40\",\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"},\"metadata\":{\"name\":\"Success Stories\"}} -->\n<div class=\"wp-block-group alignfull has-tertiary-background-color has-background\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--60);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:columns {\"align\":\"wide\"} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"verticalAlignment\":\"stretch\",\"width\":\"40%\",\"style\":{\"spacing\":{\"blockGap\":\"0\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-stretch\" style=\"flex-basis:40%\"><!-- wp:group {\"align\":\"wide\",\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"center\",\"contentSize\":\"\"}} -->\n<div class=\"wp-block-group alignwide\"><!-- wp:heading {\"fontSize\":\"large\"} -->\n<h2 class=\"wp-block-heading has-large-font-size\">What Our Travelers Say About Us</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<p style=\"margin-top:16px\">Discover how our personalized tours bring Qatar’s rich culture and history to life, ensuring every moment is unforgettable.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|50\"}}},\"layout\":{\"type\":\"flex\"}} -->\n<div class=\"wp-block-buttons\" style=\"margin-top:var(--wp--preset--spacing--40);margin-bottom:var(--wp--preset--spacing--50)\"><!-- wp:button {\"className\":\"is-style-fill\"} -->\n<div class=\"wp-block-button is-style-fill\"><a class=\"wp-block-button__link wp-element-button\" href=\"https://eyeshottourism.com/contact\">Read Testimonials</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:media-text {\"align\":\"wide\",\"mediaPosition\":\"right\",\"mediaType\":\"image\",\"mediaWidth\":40,\"imageFill\":true,\"className\":\"extendify-image-import\",\"backgroundColor\":\"background\"} -->\n<div class=\"wp-block-media-text alignwide has-media-on-the-right is-stacked-on-mobile is-image-fill-element extendify-image-import has-background-background-color has-background\" style=\"grid-template-columns:auto 40%\"><div class=\"wp-block-media-text__content\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|40\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--40)\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.5rem\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:1.5rem\">Journeys That Left Lasting Impressions</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<p style=\"margin-top:16px\">Hear from guests who experienced Qatar’s heritage and modern charm through our immersive, detail-focused tours.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div><figure class=\"wp-block-media-text__media\"><img src=\"https://images.unsplash.com/photo-1596075780750-81249df16d19?fit=crop&amp;crop=entropy%2Cfaces&amp;auto=format%2Ccompress&amp;w=1280\" alt=\"\" style=\"object-position:50% 50%\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"align\":\"wide\",\"mediaPosition\":\"right\",\"mediaType\":\"image\",\"mediaWidth\":40,\"imageFill\":true,\"className\":\"extendify-image-import\",\"backgroundColor\":\"background\"} -->\n<div class=\"wp-block-media-text alignwide has-media-on-the-right is-stacked-on-mobile is-image-fill-element extendify-image-import has-background-background-color has-background\" style=\"grid-template-columns:auto 40%\"><div class=\"wp-block-media-text__content\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|40\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--40)\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.5rem\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:1.5rem\">Creating Unique Experiences with Personalized Service</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<p style=\"margin-top:16px\">See how our boutique tours have delighted visitors with curated routes, expert guides, and exceptional care.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div><figure class=\"wp-block-media-text__media\"><img src=\"https://images.unsplash.com/photo-1600600457585-570c2eb88b89?fit=crop&amp;crop=entropy%2Cfaces&amp;auto=format%2Ccompress&amp;w=1280\" alt=\"\" style=\"object-position:50% 50%\"/></figure></div>\n<!-- /wp:media-text --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --><!-- wp:group {\"align\":\"full\",\"backgroundColor\":\"background\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"right\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|30\"},\"blockGap\":\"var:preset|spacing|40\",\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"},\"metadata\":{\"name\":\"Trust Badges\"}} -->\n<div class=\"wp-block-group alignfull has-background-background-color has-background\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--60);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:columns {\"align\":\"wide\"} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column -->\n<div class=\"wp-b