\"><!-- wp:media-text {\"mediaId\":148,\"mediaType\":\"image\",\"mediaWidth\":83,\"className\":\"ext-aspect-landscape extendify-image-import\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile ext-aspect-landscape extendify-image-import\" style=\"grid-template-columns:83% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"https://eyeshottourism.com/wp-content/uploads/2025/11/2025-11-26-10-04-37-8b3dd4b0-764d-4031-8d1f-323a586231f3-3.jpg\" alt=\"\" class=\"wp-image-148 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Content…\"} -->\n<p class=\"has-text-align-center\"><strong>Book Now</strong></p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3,\"style\":{\"spacing\":{\"margin\":{\"top\":\"24px\"}},\"typography\":{\"fontSize\":\"20px\",\"lineHeight\":\"1.5\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"margin-top:24px;font-size:20px;line-height:1.5\">Cultural Heritage Hub</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"8px\"}}},\"fontSize\":\"small\"} -->\n<p class=\"has-small-font-size\" style=\"margin-top:8px\">Tailored cultural and historical tours designed just for you.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"style\":{\"dimensions\":{\"minHeight\":\"100%\"},\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":\"4px\"}},\"backgroundColor\":\"tertiary\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-tertiary-background-color has-background\" style=\"border-radius:4px;min-height:100%;padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--