(171, 1, '2025-11-26 12:40:51', '2025-11-26 12:40:51', '<!-- wp:group {\"metadata\":{\"name\":\"Hero Header\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"right\":\"0\",\"left\":\"0\",\"bottom\":\"0\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"backgroundColor\":\"background\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-background-background-color has-background\" style=\"margin-top:0;margin-bottom:0;padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:cover {\"url\":\"https://eyeshottourism.com/wp-content/uploads/2025/11/2025-11-26-08-50-50-8b3dd4b0-764d-4031-8d1f-323a586231f3-1.jpg\",\"id\":129,\"dimRatio\":60,\"overlayColor\":\"black\",\"isUserOverlayColor\":true,\"focalPoint\":{\"x\":0.42,\"y\":0.47},\"contentPosition\":\"center center\",\"align\":\"full\",\"className\":\"extendify-image-import\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\"}}}} -->\n<div class=\"wp-block-cover alignfull extendify-image-import\" style=\"padding-right:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--30)\"><img class=\"wp-block-cover__image-background wp-image-129\" alt=\"\" src=\"https://eyeshottourism.com/wp-content/uploads/2025/11/2025-11-26-08-50-50-8b3dd4b0-764d-4031-8d1f-323a586231f3-1.jpg\" style=\"object-position:42% 47%\" data-object-fit=\"cover\" data-object-position=\"42% 47%\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-black-background-color has-background-dim-60 has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|80\",\"bottom\":\"var:preset|spacing|80\",\"left\":\"0\",\"right\":\"0\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:var(--wp--preset--spacing--80);padding-right:0;padding-bottom:var(--wp--preset--spacing--80);padding-left:0\"><!-- wp:group {\"align\":\"wide\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"wp-block-group alignwide\"><!-- wp:group {\"align\":\"wide\",\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"left\"}} -->\n<div class=\"wp-block-group alignwide\"><!-- wp:heading {\"level\":1,\"textColor\":\"white\"} -->\n<h1 class=\"wp-block-heading has-white-color has-text-color\">Personalized Journeys and Adventures Through Vibrant Qatar</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}},\"textColor\":\"white\"} -->\n<p class=\"has-white-color has-text-color\" style=\"margin-top:16px\">Qatar Tourism: Discover immersive tours, desert safaris, aquatic excursions exclusive adventures that reveal Qatar\'s rich heritage, modern marvels, and hidden gems, crafted with meticulous attention to detail for an unforgettable experience.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"style\":{\"spacing\":{\"blockGap\":\"1rem\",\"margin\":{\"top\":\"var:preset|spacing|40\"}}}} -->\n<div class=\"wp-block-buttons\" style=\"margin-top:var(--wp--preset--spacing--40)\"><!-- wp:button {\"style\":{\"color\":{\"background\":\"#fcfcfc\",\"text\":\"#111111\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#111111\"}}}}} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-text-color has-background has-link-color wp-element-button\" href=\"https://eyeshottourism.com/services\" style=\"color:#111111;background-color:#fcfcfc\">Discover Now</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:cb/carousel-v2 -->\n<div class=\"wp-block-cb-carousel-v2 cb-carousel-block\" data-cb-slides-per-view=\"1\" data-cb-slides-per-group=\"1\" data-cb-space-between=\"15\" data-cb-speed=\"300\" data-cb-navigation=\"true\" data-cb-pagination=\"true\" data-cb-breakpoints=\"{&quot;768&quot;:{&quot;slidesPerView&quot;:3,&quot;slidesPerGroup&quot;:1}}\"><div class=\"swiper\"><div class=\"cb-wrapper swiper-wrapper\"></div></div><div class=\"cb-pagination swiper-pagination\"></div><div class=\"cb-button-prev swiper-button-prev\"></div><div class=\"cb-button-next swiper-button-next\"></div></div>\n<!-- /wp:cb/carousel-v2 --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"About Us\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"right\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|30\"},\"blockGap\":\"var:preset|spacing|40\",\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"backgroundColor\":\"tertiary\",\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-tertiary-background-color has-background\" id=\"about\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--60);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:heading {\"textAlign\":\"center\",\"fontSize\":\"large\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-large-font-size\">Personalized Journeys Through Qatar\'s Rich Heritage. </h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<p class=\"has-text-align-center\" style=\"margin-top:16px\">At Eyeshot Tourism, we are dedicated to delivering immersive tour experiences that celebrate Qatar’s culture, history, and modern charm. Our mission is to create tailored tours with meticulous attention to detail, ensuring every traveler feels connected and inspired.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":124,\"width\":\"672px\",\"height\":\"auto\",\"aspectRatio\":\"1.7777777777777777\",\"scale\":\"cover\",\"sizeSlug\":\"large\",\"linkDestination\":\"media\",