(183, 1, '2025-11-27 02:10:15', '2025-11-27 02:10:15', '<!-- wp:group {\"metadata\":{\"name\":\"Tour Experience Highlights\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"right\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|30\"},\"blockGap\":\"var:preset|spacing|60\",\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"backgroundColor\":\"background\",\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-background-background-color has-background\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--60);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|40\",\"left\":\"var:preset|spacing|40\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"align\":\"wide\",\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"center\",\"contentSize\":\"\"}} -->\n<div class=\"wp-block-group alignwide\"><!-- wp:heading {\"fontSize\":\"large\"} -->\n<h2 class=\"wp-block-heading has-large-font-size\">Service Overview</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<p style=\"margin-top:16px\">Discover the unique elements of our personalized tours, crafted to immerse you in Qatar’s rich culture, history, and modern marvels, ensuring a memorable journey.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|30\"}}},\"layout\":{\"type\":\"flex\"}} -->\n<div class=\"wp-block-buttons\" style=\"margin-top:var(--wp--preset--spacing--30)\"><!-- wp:button {\"className\":\"is-style-fill\"} -->\n<div class=\"wp-block-button is-style-fill\"><a class=\"wp-block-button__link wp-element-button\" href=\"https://eyeshottourism.com/contact\">Discover Tours</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"1.25rem\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"verticalAlignment\":\"top\"}} -->\n<div class=\"wp-block-group\"><!-- wp:image {\"scale\":\"cover\",\"sizeSlug\":\"large\",\"className\":\"ext-aspect-landscape extendify-image-import\",\"style\":{\"color\":{\"duotone\":\"var:preset|duotone|primary-foreground\"}}} -->\n<figure class=\"wp-block-image size-large ext-aspect-landscape extendify-image-import\"><img src=\"data:image/svg+xml;base64,\" alt=\"\" style=\"object-fit:cover\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"style\":{\"layout\":{\"selfStretch\":\"fixed\",\"flexSize\":\"100%\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"20px\",\"lineHeight\":\"1.5\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:20px;line-height:1.5\">Customized Cultural Journeys</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"4px\"}}},\"fontSize\":\"small\"} -->\n<p class=\"has-small-font-size\" style=\"margin-top:4px\">Tailored itineraries focus on authentic cultural immersion, connecting you with local traditions and heritage for a truly meaningful experience.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"1.25rem\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"verticalAlignment\":\"top\"}} -->\n<div class=\"wp-block-group\"><!-- wp:image {\"scale\":\"cover\",\"sizeSlug\":\"large\",\"className\":\"ext-aspect-landscape extendify-image-import\",\"style\":{\"color\":{\"duotone\":\"var:preset|duotone|primary-foreground\"}}} -->\n<figure class=\"wp-block-image size-large ext-aspect-landscape extendify-image-import\"><img src=\"data:image/svg+xml;base64,\" alt=\"\" style=\"object-fit:cover\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"style\":{\"layout\":{\"selfStretch\":\"fixed\",\"flexSize\":\"100%\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"20px\",\"lineHeight\":\"1.5\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:20px;line-height:1.5\">Expert Local Guides</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"4px\"}}},\"fontSize\":\"small\"} -->\n<p class=\"has-small-font-size\" style=\"margin-top:4px\">Knowledgeable guides provide in-depth insights and personalized attention, enhancing your understanding and enjoyment throughout the tour.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:cover {\"url\":\"https://images.unsplash.com/photo-1758622799261-28e79a90eca9?ixid=M3w0MzUxNjF8MHwxfHNlYXJjaHwxMnx8UWF0YXIlMjB0b3VyaXNtfGVufDB8fHx8MTc2MzAzOTYwNHww\\u0026ixlib=rb-4.1.0\\u0026orientation=portrait?fit=crop\\u0026crop=entropy%2Cfaces\\u0026auto=format%2Ccompress\\u0026w=1280\",\"dimRatio\":0,\"contentPosition\":\"center center\",\"align\":\"full\",\"className\":\"extendify-image-import\",\"style\":{\"color\":[],\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"right\":\"0\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-cover alignfull extendify-image-import\" style=\"margin-top:0;margin-bottom:0;padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><img class=\"wp-block-cover__image-background\" alt=\"\" src=\"https://images.unsplash.com/photo-1758622799261-28e79a90eca9?ixid=M3w0MzUxNjF8MHwxfHNlYXJjaHwxMnx8UWF0YXIlMjB0b3VyaXNtfGVufDB8fHx8MTc2MzAzOTYwNHww&amp;ixlib=rb-4.1.0&amp;orientation=portrait?fit=crop&amp;crop=entropy%2Cfaces&amp;auto=format%2Ccompress&amp;w=1280\" data-object-fit=\"cover\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-0 has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:spacer {\"height\":\"380px\"} -->\n<div style=\"height:380px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\" Resource\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|20\",\"right\":\"var:preset|spacing|20\",\"bottom\":\"var:preset|spacing|20\",\"left\":\"var:preset|spacing|20\"},\"blockGap\":\"var:preset|spacing|20\",\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"dimensions\":{\"minHeight\":\"0px\"},\"border\":{\"width\":\"10px\"}},\"backgroundColor\":\"background\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"wp-block-group alignfull has-background-background-color has-background\" id=\"service-area\" style=\"border-width:10px;min-height:0px;margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--20);padding-right:var(--wp--preset--spacing--20);padding-bottom:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--20)\"><!-- wp:group {\"align\":\"wide\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"wp-block-group alignwide\"><!-- wp:group {\"align\":\"wide\",\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"left\",\"contentSize\":\"\"}} -->\n<div class=\"wp-block-group alignwide\"><!-- wp:heading {\"textAlign\":\"left\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"right\":\"0\"}}},\"fontSize\":\"large\"} -->\n<h2 class=\"wp-block-heading has-text-align-left has-large-font-size\" style=\"margin-top:0;margin-right:0;margin-bottom:0;margin-left:0\">Explore Qatar\'s Rich Heritage and Vibrant Present. </h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<p style=\"margin-top:16px\">Our Qatar Tourism proudly offer personalized tours across Qatar\'s most captivating destinations.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|70\",\"left\":\"var:preset|spacing|30\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"style\":{\"dimensions\":{\"minHeight\":\"100%\"},\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"blockGap\":\"var:preset|spacing|30\"},\"border\":{\"radius\":\"4px\",\"width\":\"0px\",\"style\":\"none\"}},\"backgroundColor\":\"tertiary\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-tertiary-background-color has-background\" style=\"border-style:none;border-width:0px;border-radius:4px;min-height:100%;margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"24px\"}},\"typography\":{\"fontSize\":\"20px\",\"lineHeight\":\"1.5\"},\"color\":{\"text\":\"#666161\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#666161\"}}}}} -->\n<h4 class=\"wp-block-heading has-text-align-center has-text-color has-link-color\" style=\"color:#666161;margin-top:24px;font-size:20px;line-height:1.5\">Doha City Tours</h4>\n<!-- /wp:heading -->\n\n<!-- wp:cover {\"url\":\"https://eyeshottourism.com/wp-content/uploads/2025/11/2025-11-26-08-50-50-8b3dd4b0-764d-4031-8d1f-323a586231f3-5-1024x683.jpg\",\"id\":144,\"dimRatio\":50,\"align\":\"full\"} -->\n<div class=\"wp-block-cover alignfull\"><img class=\"wp-block-cover__image-background wp-image-144\" alt=\"\" src=\"https://eyeshottourism.com/wp-content/uploads/2025/11/2025-11-26-08-50-50-8b3dd4b0-764d-4031-8d1f-323a586231f3-5-1024x683.jpg\" data-object-fit=\"cover\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Content…\"} -->\n<p class=\"has-text-align-center\">Discover Doha\'s seamless blend of ancient tradition and futuristic vision. Experience expert private guidance and attentive service as your tour the captivating cityscape and iconic modern marvels.</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"style\":{\"dimensions\":{\"minHeight\":\"100%\"},\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":\"4px\"}},\"backgroundColor\":\"tertiary\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-tertiary-background-color has-background\" style=\"border-radius:4px;min-height:100%;padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"24px\"}},\"typography\":{\"fontSize\":\"20px\",\"lineHeight\":\"1.5\"},\"color\":{\"text\":\"#666161\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#666161\"}}}}} -->\n<h4 class=\"wp-block-heading has-text-align-center has-text-color has-link-color\" style=\"color:#666161;margin-top:24px;font-size:20px;line-height:1.5\">Cultural Heritage Hub</h4>\n<!-- /wp:heading -->\n\n<!-- wp:cover {\"url\":\"https://eyeshottourism.com/wp-content/uploads/2025/11/2025-11-26-10-04-37-8b3dd4b0-764d-4031-8d1f-323a586231f3-3.jpg\",\"id\":148,\"dimRatio\":50,\"align\":\"full\"} -->\n<div class=\"wp-block-cover alignfull\"><img class=\"wp-block-cover__image-background wp-image-148\" alt=\"\" src=\"https://eyeshottourism.com/wp-content/uploads/2025/11/2025-11-26-10-04-37-8b3dd4b0-764d-4031-8d1f-323a586231f3-3.jpg\" data-object-fit=\"cover\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Content…\"} -->\n<p class=\"has-text-align-center\">Tailored cultural and historical tours designed just for you.</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"style\":{\"dimensions\":{\"minHeight\":\"100%\"},\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":\"4px\"}},\"backgroundColor\":\"tertiary\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-tertiary-background-color has-background\" style=\"border-radius:4px;min-height:100%;padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"24px\"}},\"typography\":{\"fontSize\":\"20px\",\"lineHeight\":\"1.5\"},\"color\":{\"text\":\"#666161\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#666161\"}}