agraph -->\n\n<!-- wp:social-links {\"iconColor\":\"foreground\",\"iconColorValue\":\"#0B0620\",\"size\":\"has-small-icon-size\",\"className\":\"is-style-logos-only\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"16px\",\"left\":\"16px\"},\"margin\":{\"top\":\"24px\"}}},\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<ul class=\"wp-block-social-links has-small-icon-size has-icon-color is-style-logos-only\" style=\"margin-top:24px\"><!-- wp:social-link {\"url\":\"#\",\"service\":\"twitter\"} /-->\n\n<!-- wp:social-link {\"url\":\"#\",\"service\":\"linkedin\"} /--></ul>\n<!-- /wp:social-links --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\" Testimonial\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"right\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|30\"},\"blockGap\":\"var:preset|spacing|40\",\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"backgroundColor\":\"background\",\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-background-background-color has-background\" id=\"testimonials\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--60);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:group {\"align\":\"wide\",\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"center\",\"contentSize\":\"\"}} -->\n<div class=\"wp-block-group alignwide\"><!-- wp:heading {\"textAlign\":\"center\",\"fontSize\":\"large\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-large-font-size\">Personalized Journeys Through Qatar\'s Rich Heritage</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<p class=\"has-text-align-center\" style=\"margin-top:16px\">Hear from our guests about their immersive and memorable tours with Eyeshot Tourism.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"align\":\"wide\"} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"verticalAlignment\":\"stretch\"} -->\n<div class=\"wp-block-column is-vertically-aligned-stretch\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":\"4px\"},\"dimensions\":{\"minHeight\":\"100%\"}},\"backgroundColor\":\"tertiary\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-tertiary-background-color has-background\" style=\"border-radius:4px;min-height:100%;padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:image {\"sizeSlug\":\"large\",\"className\":\"extendify-image-import\",\"style\":{\"color\":{\"duotone\":\"var:preset|duotone|primary-foreground\"}}} -->\n<figure class=\"wp-block-image size-large extendify-image-import\"><img src=\"data:image/svg+xml;base64,\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\"},\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|20\"}}}} -->\n<p style=\"margin-top:var(--wp--preset--spacing--20);font-style:normal;font-weight:500\">Exploring Qatar with Eyeshot Tourism was an unforgettable experience that exceeded all my expectations.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"1rem\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:image {\"id\":177,\"width\":\"66px\",\"height\":\"auto\",\"scale\":\"cover\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\",\"className\":\"is-style-rounded extendify-image-import\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized is-style-rounded extendify-image-import\"><img src=\"https://eyeshottourism.com/wp-content/uploads/2025/11/image.jpg\" alt=\"\" class=\"wp-image-177\" style=\"object-fit:cover;width:66px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"level\":4,\"fontSize\":\"small\"} -->\n<h4 class=\"wp-block-heading has-small-font-size\">Younus</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"2px\"}}},\"fontSize\":\"small\"} -->\n<p class=\"has-small-font-size\" style=\"margin-top:2px\">Cultural Enthusiast &amp; Travel Blogger</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"stretch\"} -->\n<div class=\"wp-block-column is-vertically-aligned-stretch\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":\"4px\"},\"dimensions\":{\"minHeight\":\"100%\"}},\"backgroundColor\":\"tertiary\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-tertiary-background-color has-background\" style=\"border-radius:4px;min-height:100%;padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:image {\"sizeSlug\":\"large\",\"className\":\"extendify-image-import\",\"style\":{\"color\":{\"duotone\":\"var:preset|duotone|primary-foreground\"}}} -->\n<figure class=\"wp-block-image size-large extendify-image-import\"><img src=\"data:image/svg+xml;base64,\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\"},\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|20\"}}}} -->\n<p style=\"margin-top:var(--wp--preset--spacing--20);font-style:normal;font-weight:500\">The team’s attention to detail and deep knowledge made every moment of our tour truly exceptional.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"1rem\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:image {\"id\":196,\"width\":\"65px\",\"height\":\"auto\",\"aspectRatio\":\"1\",\"scale\":\"cover\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\",\"className\":\"is-style-rounded extendify-image-import\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized is-style-rounded extendify-image-import\"><img src=\"https://eyeshottourism.com/wp-content/uploads/2025/11/1764223667542.png\" alt=\"\" class=\"wp-image-196\" style=\"aspect-ratio:1;object-fit:cover;width:65px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"level\":4,\"fontSize\":\"small\"} -->\n<h4 class=\"wp-block-heading has-small-font-size\">Okezi</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"2px\"}}},\"fontSize\":\"small\"} -->\n<p class=\"has-small-font-size\" style=\"margin-top:2px\">History Professor</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"stretch\"} -->\n<div class=\"wp-block-column is-vertically-aligned-stretch\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":\"4px\"},\"dimensions\":{\"minHeight\":\"100%\"}},\"backgroundColor\":\"tertiary\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-tertiary-background-color has-background\" style=\"border-radius:4px;min-height:100%;padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:image {\"sizeSlug\":\"large\",\"className\":\"extendify-image-import\",\"style\":{\"color\":{\"duotone\":\"var:preset|duotone|primary-foreground\"}}} -->\n<figure class=\"wp-block-image size-large extendify-image-import\"><img src=\"data:image/svg+xml;base64,\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\"},\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|20\"}}}} -->\n<p style=\"margin-top:var(--wp--preset--spacing--20);font-style:normal;font-weight:500\">Every aspect of the tour was thoughtfully planned, leaving me fully satisfied and inspired.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"1rem\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:image {\"id\":189,\"width\":\"63px\",\"height\":\"auto\",\"aspectRatio\":\"1\",\"scale\":\"cover\",\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"align\":\"center\",\"className\":\"is-style-rounded extendify-image-import\"} -->\n<figure class=\"wp-block-image aligncenter size-large is-resized is-style-rounded extendify-image-import\"><img src=\"https://eyeshottourism.com/wp-content/uploads/2025/11/1764222284640-1024x683.png\" alt=\"\" class=\"wp-image-189\" style=\"aspect-ratio:1;object-fit:cover;width:63px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"level\":4,\"fontSize\":\"small\"} -->\n<h4 class=\"wp-block-heading has-small-font-size\">Lina</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"2px\"}}},\"fontSize\":\"small\"} -->\n<p class=\"has-small-font-size\" style=\"margin-top:2px\">Luxury Travel Consultant</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->', 'About', '', 'inherit', 'closed', 'closed', '', '23-revision-v1', '', '', '2025-11-27 06:09:53', '2025-11-27 06:09:53', '', 23, 'https://eyeshottourism.com/?p=197', 0, 'revision', '', 0);
INSERT INTO `wp1l_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(199, 1, '2025-11-27 06:18:17', '2025-11-27 06:18:17', '<!-- wp:group {\"metadata\":{\"name\":\"About Us\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"right\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|30\"},\"blockGap\":\"var:preset|spacing|40\",\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"backgroundColor\":\"background\",\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-background-background-color has-background\" id=\"about\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--60);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:heading {\"textAlign\":\"center\",\"fontSize\":\"large\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-large-font-size\">Experience the Heart of Qatar Through Our Tours</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<p class=\"has-text-align-center\" style=\"margin-top:16px\">At Eyeshot Tourism, we are dedicated to delivering personalized journeys that immerse you in Qatar’s unique heritage and modern charm, ensuring every moment is crafted with care and commitment to your satisfaction.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:gallery {\"linkTo\":\"none\",\"align\":\"wide\"} -->\n<figure class=\"wp-block-gallery alignwide has-nested-images columns-default is-cropped\"><!-- wp:image {\"aspectRatio\":\"3/4\",\"scale\":\"cover\",\"className\":\"extendify-image-import\"} -->\n<figure class=\"wp-block-image extendify-image-import\"><img src=\"https://images.unsplash.com/photo-1758622799499-24576f36c464?ixid=M3w0MzUxNjF8MHwxfHNlYXJjaHw4fHxRYXRhciUyMHRvdXJpc218ZW58MHx8fHwxNzYzMDM5NjA0fDA&amp;ixlib=rb-4.1.0&amp;orientation=portrait?fit=crop&amp;crop=entropy%2Cfaces&amp;auto=format%2Ccompress&amp;w=1280\" alt=\"\" style=\"aspect-ratio:3/4;object-fit:cover\"/><figcaption class=\"wp-element-caption\">Our vision is to be the most trusted and sought-after luxury travel partner in Qatar, recognized globally for our commitment to bespoke service and immersive, high-quality experiences. We aim to redefine luxury tourism by setting a new standard for personalization, where your preferences shape every detail of your journey, from your hotel accommodation to your daily itinerary</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"aspectRatio\":\"3/4\",\"scale\":\"cover\",\"className\":\"extendify-image-import\"} -->\n<figure class=\"wp-block-image extendify-image-import\"><img src=\"https://images.unsplash.com/photo-1758389232467-10d8cdf9babc?ixid=M3w0MzUxNjF8MHwxfHNlYXJjaHw3fHxRYXRhciUyMHRvdXJpc218ZW58MHx8fHwxNzYzMDM5NjA0fDA&amp;ixlib=rb-4.1.0&amp;orientation=landscape?fit=crop&amp;crop=entropy%2Cfaces&amp;auto=format%2Ccompress\" alt=\"\" style=\"aspect-ratio:3/4;object-fit:cover\"/><figcaption class=\"wp-element-caption\">Our mission is to flawlessly connect you with the authentic and exciting experiences that Qatar offers. We achieve this by providing a comprehensive suite of services that ensure comfort, excitement, and cultural immersion</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"aspectRatio\":\"3/4\",\"scale\":\"cover\",\"className\":\"extendify-image-import\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n<figure class=\"wp-block-image extendify-image-import\" style=\"margin-top:0;margin-bottom:0\"><img src=\"https://images.unsplash.com/photo-1758622799261-28e79a90eca9?ixid=M3w0MzUxNjF8MHwxfHNlYXJjaHwxMnx8UWF0YXIlMjB0b3VyaXNtfGVufDB8fHx8MTc2MzAzOTYwNHww&amp;ixlib=rb-4.1.0&amp;orientation=portrait?fit=crop&amp;crop=entropy%2Cfaces&amp;auto=format%2Ccompress\" alt=\"\" style=\"aspect-ratio:3/4;object-fit:cover\"/><figcaption class=\"wp-element-caption\">Our Core Values: The Eyeshot Tourism Promise<br>&nbsp;* Personalization: Every itinerary is designed around you. We avoid one-size-fits-all packages.<br>* Commitment to Safety &amp; Care: Your satisfaction and safety are paramount. We are dedicated to providing the highest standards of service and guaranteed on-time execution.<br>&nbsp;* Local Expertise: We are proud to showcase the beauty and heritage of Qatar.<br>&nbsp;* 24/7 Support: Our team is available around the clock to ensure your trip is flawless, from planning to departure.</figcaption></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\" Team\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"right\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|30\"},\"blockGap\":\"var:preset|spacing|30\",\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"backgroundColor\":\"tertiary\",\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-tertiary-background-color has-background\" id=\"team\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--60);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:group {\"align\":\"wide\",\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"center\",\"contentSize\":\"\"}} -->\n<div class=\"wp-block-group alignwide\"><!-- wp:heading {\"textAlign\":\"center\",\"fontSize\":\"large\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-large-font-size\">Discover Qatar’s Hidden Gems</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<p class=\"has-text-align-center\" style=\"margin-top:16px\">Meet the passionate experts dedicated to crafting your unique Qatar journey.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Every member of the Eyeshot Tourism team operates under a set of non-negotiable values:</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|50\"}}}} -->\n<div class=\"wp-block-columns alignwide\" style=\"margin-top:var(--wp--preset--spacing--50)\"><!-- wp:column {\"backgroundColor\":\"background\"} -->\n<div class=\"wp-block-column has-background-background-color has-background\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"24px\",\"right\":\"24px\",\"bottom\":\"24px\",\"left\":\"24px\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:24px;padding-right:24px;padding-bottom:24px;padding-left:24px\"><!-- wp:image {\"id\":40,\"aspectRatio\":\"1\",\"scale\":\"cover\",\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"align\":\"center\",\"className\":\"extendify-image-import is-style-rounded\"} -->\n<figure class=\"wp-block-image aligncenter size-large extendify-image-import is-style-rounded\"><img src=\"https://eyeshottourism.com/wp-content/uploads/2025/11/Final-3D-1-1024x1024.png\" alt=\"\" class=\"wp-image-40\" style=\"aspect-ratio:1;object-fit:cover\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"20px\"}},\"typography\":{\"fontSize\":\"20px\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:20px;font-size:20px\">M Hares</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"4px\"}}},\"textColor\":\"primary\",\"fontSize\":\"small\"} -->\n<p class=\"has-text-align-center has-primary-color has-text-color has-small-font-size\" style=\"margin-top:4px\">Founder &amp; Chairman</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\