-->\n\n<!-- wp:social-links {\"iconColor\":\"foreground\",\"iconColorValue\":\"#0B0620\",\"size\":\"has-small-icon-size\",\"className\":\"is-style-logos-only\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"16px\",\"left\":\"16px\"},\"margin\":{\"top\":\"24px\"}}},\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<ul class=\"wp-block-social-links has-small-icon-size has-icon-color is-style-logos-only\" style=\"margin-top:24px\"><!-- wp:social-link {\"url\":\"#\",\"service\":\"twitter\"} /-->\n\n<!-- wp:social-link {\"url\":\"#\",\"service\":\"linkedin\"} /--></ul>\n<!-- /wp:social-links --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\" Testimonial\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"right\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|30\"},\"blockGap\":\"var:preset|spacing|40\",\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"backgroundColor\":\"background\",\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-background-background-color has-background\" id=\"testimonials\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--60);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:group {\"align\":\"wide\",\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"center\",\"contentSize\":\"\"}} -->\n<div class=\"wp-block-group alignwide\"><!-- wp:heading {\"textAlign\":\"center\",\"fontSize\":\"large\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-large-font-size\">Personalized Journeys Through Qatar\'s Rich Heritage</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<p class=\"has-text-align-center\" style=\"margin-top:16px\">Hear from our guests about their immersive and memorable tours with Eyeshot Tourism.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"align\":\"wide\"} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"verticalAlignment\":\"stretch\"} -->\n<div class=\"wp-block-column is-vertically-aligned-stretch\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":\"4px\"},\"dimensions\":{\"minHeight\":\"100%\"}},\"backgroundColor\":\"tertiary\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-tertiary-background-color has-background\" style=\"border-radius:4px;min-height:100%;padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:image {\"sizeSlug\":\"large\",\"className\":\"extendify-image-import\",\"style\":{\"color\":{\"duotone\":\"var:preset|duotone|primary-foreground\"}}} -->\n<figure class=\"wp-block-image size-large extendify-image-import\"><img src=\"data:image/svg+xml;base64,\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\"},\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|20\"}}}} -->\n<p style=\"margin-top:var(--wp--preset--spacing--20);font-style:normal;font-weight:500\">Exploring Qatar with Eyeshot Tourism was an unforgettable experience that exceeded all my expectations.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"1rem\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:image {\"id\":177,\"width\":\"66px\",\"height\":\"auto\",\"scale\":\"cover\",\"sizeSlug\":\"full\",\"linkDe