group has-tertiary-background-color has-background\" style=\"border-radius:100px;min-height:96px;padding-top:var(--wp--preset--spacing--20);padding-right:var(--wp--preset--spacing--20);padding-bottom:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--20)\"><!-- wp:image {\"sizeSlug\":\"large\",\"align\":\"center\",\"className\":\"extendify-image-import\",\"style\":{\"color\":{\"duotone\":\"var:preset|duotone|secondary-and-primary\"}}} -->\n<figure class=\"wp-block-image aligncenter size-large extendify-image-import\"><img src=\"data:image/svg+xml;base64,\" alt=\"\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"spacing\":{\"margin\":{\"top\":\"24px\"}},\"typography\":{\"fontSize\":\"1.25rem\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:24px;font-size:1.25rem\">Secure Payment Guarantee</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"8px\"}}},\"fontSize\":\"small\"} -->\n<p class=\"has-text-align-center has-small-font-size\" style=\"margin-top:8px\">Our encrypted payment system protects your personal information, providing a safe and seamless booking experience.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group\"><!-- wp:group {\"style\":{\"border\":{\"radius\":\"100px\"},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|20\",\"bottom\":\"var:preset|spacing|20\",\"left\":\"var:preset|spacing|20\",\"right\":\"var:preset|spacing|20\"}},\"layout\":{\"selfStretch\":\"fixed\",\"flexSize\":\"96px\"},\"dimensions\":{\"minHeight\":\"96px\"}},\