 );\\nfunction eyeshot_change_related_products_text( $translated_text, $text, $domain ) {\\n    if ( $text === \'Related products\' && $domain === \'woocommerce\' ) {\\n        $translated_text = \'Other Popular Tours\'; \\/\\/ Change this to your preferred title\\n    }\\n    return $translated_text;\\n}\\n\",\"spacing\":{\"padding\":{\"top\":\"0\",\"right\":\"var(--wp--preset--spacing--30)\",\"bottom\":\"0\",\"left\":\"var(--wp--preset--spacing--30)\"},\"blockGap\":\"0\"},\"elements\":{\"heading\":{\"color\":{\"text\":\"var(--wp--preset--color--foreground)\"}},\"link\":{\"color\":{\"text\":\"#612e34\"}}},\"color\":{\"text\":\"#612e34\"}},\"settings\":{\"custom\":{\"elements\":{\"button\":{\":hover\":{\"color\":{\"background\":\"var(--wp--preset--color--foreground)\",\"text\":\"var(--wp--preset--color--background)\"}},\":focus\":{\"color\":{\"background\":\"var(--wp--preset--color--primary)\",\"text\":\"var(--wp--preset--color--background)\"}},\"color\":{\"background\":\"var(--wp--preset--color--primary)\",\"text\":\"var(--wp--preset--color--background)\"}}}},\"color\":{\"duotone\":{\"theme\":[{\"colors\":[\"#212023\",\"#744F39\"],\"slug\":\"primary-and-secondary\",\"name\":\"Primary and secondary\"},{\"colors\":[\"#212023\",\"#F9F8F1\"],\"slug\":\"primary-and-tertiary\",\"name\":\"Primary and tertiary\"},{\"colors\":[\"#744F39\",\"#212023\"],\"slug\":\"secondary-and-primary\",\"name\":\"Secondary and primary\"},{\"colors\":[\"#582A2F\",\"#FBEBE1\"],\"slug\":\"foreground-and-background\",\"name\":\"Foreground and background\"},{\"colors\":[\"#212023\",\"#582A2F\"],\"slug\":\"primary-foreground\",\"name\":\"Primary and Foreground\"},{\"colors\":[\"#FBEBE1\",\"#F9F8F1\"],\"slug\":\"background-tertiary\",\"name\":\"Background and Background Alt\"}]},\"palette\":{\"theme\":[{\"slug\":\"background\",\"color\":\"#FBEBE1\",\"name\":\"Background\"},{\"slug\":\"foreground\",\"color\":\"#582A2F\",\"name\":\"Foreground\"},{\"slug\":\"primary\",\"color\":\"#212023\",\"name\":\"Primary\"},{\"slug\":\"secondary\",\"color\":\"#744F39\",\"name\":\"Secondary\"},{\"slug\":\"tertiary\",\"color\":\"#F9F8F1\",\"name\":\"Tertiary\"},{\"slug\":\"foreground-alt\",\"color\":\"#4C3B35\",\"name\":\"Foreground Alt\"}]}}},\"isGlobalStylesUserThemeJSON\":true,\"version\":3}', 'Custom Styles', '', 'inherit', 'closed', 'closed', '', '5-revision-v1', '', '', '2026-02-03 10:21:35', '2026-02-03 10:21:35', '', 5, 'https://eyeshottourism.com/?p=646', 0, 'revision', '', 0),
