},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"right\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|30\"},\"blockGap\":\"var:preset|spacing|40\",\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"color\":{\"background\":\"#dddddd\"}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-background\" id=\"about\" style=\"background-color:#dddddd;margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--60);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:heading {\"textAlign\":\"center\",\"fontSize\":\"large\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-large-font-size\">Personalized Journeys Through Qatar\'s Rich Heritage. </h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<p class=\"has-text-align-center\" style=\"margin-top:16px\">At Eyeshot Tourism, we are dedicated to delivering immersive tour experiences that celebrate Qatar’s culture, history, and modern charm. Our mission is to create tailored tours with meticulous attention to detail, ensuring every traveler feels connected and inspired.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":124,\"width\":\"672px\",\"height\":\"auto\",\"aspectRatio\":\"1.7777777777777777\",\"scale\":\"cover\",\"sizeSlug\":\"large\",\"linkDestination\":\"media\",\"align\":\"center\",\"className\":\"extendify-image-import is-style-default\"} -->\n<figure class=\"wp-block-image aligncenter size-large is-resized extendify-image-import is-style-default\"><a href=\"https://images.unsplash.com/photo-1762254979295-8279180e8d9c?ixid=M3w0MzUxNjF8MHwxfHNlYXJjaHwxNXx8dHJhdmVsJTIwZXhwZXJpZW5jZXN8ZW58MHx8fHwxNzYyNzkxNzIzfDA&amp;ixlib=rb-4.1.0&amp;orientation=portrait?fit=crop&amp;crop=entropy%2Cfaces&amp;auto=format%2Ccompress&amp;w=1280\"><img src=\"https://eyeshottourism.com/wp-content/uploads/2025/11/2025-11-26-07-55-41-8b3dd4b0-764d-4031-8d1f-323a586231f3.jpg\" alt=\"\" class=\"wp-image-124\" style=\"aspect-ratio:1.7777777777777777;object-fit:cover;width:672px;height:auto\"/></a></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\" Resource\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"right\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|30\"},\"blockGap\":\"var:preset|spacing|50\",\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"color\":{\"background\":\"#dddddd\"}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-background\" id=\"service-area\" style=\"background-color:#dddddd;margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--60);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:group {\"align\":\"wide\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"wp-block-group alignwide\"><!-- wp:group {\"align\":\"wide\",\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"left\",\"contentSize\":\"\"}} -->\n<div class=\"wp-block-group alignwide\"><!-- wp:heading {\"fontSize\":\"large\"} -->\n<h2 class=\"wp-block-heading has-large-font-size\">Explore Qatar\'s Rich Heritage and Vibrant Present. </h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<p style=\"margin-top:16px\">Our Qatar Tourism proudly offer personalized tours across Qatar\'s most captivating destinations.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|70\",\"left\":\"var