(332, 1, '2025-12-24 13:13:37', '2025-12-24 13:13:37', '<!-- wp:group {\"metadata\":{\"name\":\"Tour Experience Highlights\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"right\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|30\"},\"blockGap\":\"var:preset|spacing|60\",\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"backgroundColor\":\"background\",\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|40\",\"left\":\"var:preset|spacing|40\"}}}} -->\n<!-- wp:column -->\n<!-- wp:group {\"align\":\"wide\",\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"center\",\"contentSize\":\"\"}} -->\n<!-- wp:heading {\"fontSize\":\"large\"} -->\n<h2>Service Overview</h2>\n<!-- /wp:heading --><!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<p style=\"margin-top: 16px;\">Discover the unique elements of our personalized tours, crafted to immerse you in Qatar’s rich culture, history, and modern marvels, ensuring a memorable journey.</p>\n<!-- /wp:paragraph --><!-- wp:buttons {\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|30\"}}},\"layout\":{\"type\":\"flex\"}} -->\n<!-- wp:button {\"className\":\"is-style-fill\"} -->\n<a href=\"https://eyeshottourism.com/contact\">Discover Tours</a>\n<!-- /wp:button -->\n<!-- /wp:buttons -->\n<!-- /wp:group -->\n<!-- /wp:column --><!-- wp:column -->\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"1.25rem\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"verticalAlignment\":\"top\"}} -->\n<!-- wp:image {\"scale\":\"cover\",\"sizeSlug\":\"large\",\"className\":\"ext-aspect-landscape extendify-image-import\",\"style\":{\"color\":{\"duotone\":\"var:preset|duotone|primary-foreground\"}}} -->\n<figure><img style=\"object-fit: cover;\" src=\"data:image/svg+xml;base64,\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:group {\"style\":{\"layout\":{\"selfStretch\":\"fixed\",\"flexSize\":\"100%\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"20px\",\"lineHeight\":\"1.5\"}}} -->\n<h3 style=\"font-size: 20px; line-height: 1.5;\">Customized Cultural Journeys</h3>\n<!-- /wp:heading --><!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"4px\"}}},\"fontSize\":\"small\"} -->\n<p style=\"margin-top: 4px;\">Tailored itineraries focus on authentic cultural immersion, connecting you with local traditions and heritage for a truly meaningful experience.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:group -->\n<!-- /wp:group --><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"1.25rem\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"verticalAlignment\":\"top\"}} -->\n<!-- wp:image {\"scale\":\"cover\",\"sizeSlug\":\"large\",\"className\":\"ext-aspect-landscape extendify-image-import\",\"style\":{\"color\":{\"duotone\":\"var:preset|duotone|primary-foreground\"}}} -->\n<figure><img style=\"object-fit: cover;\" src=\"data:image/svg+xml;base64,\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:group {\"style\":{\"layout\":{\"selfStretch\":\"fixed\",\"flexSize\":\"100%\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"20px\",\"lineHeight\":\"1.5\"}}} -->\n<h3 style=\"font-size: 20px; line-height: 1.5;\">Expert Local Guides</h3>\n<!-- /wp:heading --><!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"4px\"}}},\"fontSize\":\"small\"} -->\n<p style=\"margin-top: 4px;\">Knowledgeable guides provide in-depth insights and personalized attention, enhancing your understanding and enjoyment throughout the tour.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:group -->\n<!-- /wp:group -->\n<!-- /wp:column -->\n<!-- /wp:columns -->\n<!-- /wp:group --><!-- wp:group {\"metadata\":{\"name\":\" Resource\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|20\",\"right\":\"var:preset|spacing|20\",\"bottom\":\"var:preset|spacing|20\",\"left\":\"var:preset|spacing|20\"},\"blockGap\":\"var:preset|spacing|20\",\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"dimensions\":{\"minHeight\":\"0px\"},\"border\":{\"width\":\"0px\",\"style\":\"none\"}},\"backgroundColor\":\"background\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<!-- wp:group {\"align\":\"wide\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<!-- wp:group {\"align\":\"wide\",\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"left\",\"contentSize\":\"\"}} -->\n<!-- wp:heading {\"textAlign\":\"left\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"right\":\"0\"}}},\"fontSize\":\"large\"} -->\n<h2 style=\"margin: 0;\">Explore Qatar\'s Rich Heritage and Vibrant Present.</h2>\n<!-- /wp:heading --><!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<p style=\"margin-top: 16px;\">Our Qatar Tourism proudly offer personalized tours across Qatar\'s most captivating destinations.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:group -->\n<!-- /wp:group --><!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|70\",\"left\":\"var:preset|spacing|30\"}}}} -->\n<!-- wp:column -->\n<!-- wp:group {\"style\":{\"dimensions\":{\"minHeight\":\"100%\"},\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"blockGap\":\"var:preset|spacing|30\"},\"border\":{\"radius\":\"4px\",\"width\":\"0px\",\"style\":\"none\"}},\"backgroundColor\":\"tertiary\",\"layout\":{\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"24px\"}},\"typography\":{\"fontSize\":\"20px\",\"lineHeight\":\"1.5\"},\"color\":{\"text\":\"#666161\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#666161\"}}}}} -->\n<h4 style=\"color: #666161; margin-top: 24px; font-size: 20px; line-height: 1.5;\">Doha City Tours</h4>\n<!-- /wp:heading --><!-- wp:cover {\"url\":\"https://eyeshottourism.com/wp-content/uploads/2025/11/2025-11-26-08-50-50-8b3dd4b0-764d-4031-8d1f-323a586231f3-5-1024x683.jpg\",\"id\":144,\"dimRatio\":50,\"align\":\"full\"} -->\n<img src=\"https://eyeshottourism.com/wp-content/uploads/2025/11/2025-11-26-08-50-50-8b3dd4b0-764d-4031-8d1f-323a586231f3-5-1024x683.jpg\" alt=\"\" data-object-fit=\"cover\" />\n<!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Content…\"} -->\n<p>Discover Doha\'s seamless blend of ancient tradition and futuristic vision. Experience expert private guidance and attentive service as your tour the captivating cityscape and iconic modern marvels.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:cover -->\n<!-- /wp:group -->\n<!-- /wp:column --><!-- wp:column -->\n<!-- wp:group {\"style\":{\"dimensions\":{\"minHeight\":\"100%\"},\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":\"4px\"}},\"backgroundColor\":\"tertiary\",\"layout\":{\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"24px\"}},\"typography\":{\"fontSize\":\"20px\",\"lineHeight\":\"1.5\"},\"color\":{\"text\":\"#666161\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#666161\"}}}}} -->\n<h4 style=\"color: #666161; margin-top: 24px; font-size: 20px; line-height: 1.5;\">Cultural Heritage Hub</h4>\n<!-- /wp:heading --><!-- wp:cover {\"url\":\"https://eyeshottourism.com/wp-content/uploads/2025/11/2025-11-26-10-04-37-8b3dd4b0-764d-4031-8d1f-323a586231f3-3.jpg\",\"id\":148,\"dimRatio\":50,\"align\":\"full\"} -->\n<img src=\"https://eyeshottourism.com/wp-content/uploads/2025/11/2025-11-26-10-04-37-8b3dd4b0-764d-4031-8d1f-323a586231f3-3.jpg\" alt=\"\" data-object-fit=\"cover\" />\n<!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Content…\"} -->\n<p>Tailored cultural and historical tours designed just for you.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:cover -->\n<!-- /wp:group -->\n<!-- /wp:column --><!-- wp:column -->\n<!-- wp:group {\"style\":{\"dimensions\":{\"minHeight\":\"100%\"},\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":\"4px\"}},\"backgroundColor\":\"tertiary\",\"layout\":{\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"24px\"}},\"typography\":{\"fontSize\":\"20px\",\"lineHeight\":\"1.5\"},\"color\":{\"text\":\"#666161\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#666161\"}}}}} -->\n<h4 style=\"color: #666161; margin-top: 24px; font-size: 20px; line-height: 1.5;\">Desert Adventure Base</h4>\n<!-- /wp:heading --><!-- wp:cover {\"url\":\"https://eyeshottourism.com/wp-content/uploads/2025/11/1764156589014.png\",\"id\":158,\"dimRatio\":50,\"align\":\"full\"} -->\n<img src=\"https://eyeshottourism.com/wp-content/uploads/2025/11/1764156589014.png\" alt=\"\" data-object-fit=\"cover\" />\n<!-- wp:paragraph {\"placeholder\":\"Content…\"} -->\n<p>Engage in immersive desert experiences and bespoke excursions here.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:cover -->\n<!-- /wp:group -->\n<!-- /wp:column -->\n<!-- /wp:columns --><!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|70\",\"left\":\"var:preset|spacing|30\"}}}} -->\n<!-- wp:column -->\n<!-- wp:group {\"style\":{\"dimensions\":{\"minHeight\":\"100%\"},\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":\"4px\"}},\"backgroundColor\":\"tertiary\",\"layout\":{\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"24px\"}},\"typography\":{\"fontSize\":\"20px\",\"lineHeight\":\"1.5\"},\"color\":{\"text\":\"#666161\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#666161\"}}}}} -->\n<h4 style=\"color: #666161; margin-top: 24px; font-size: 20px; line-height: 1.5;\">Premium Airport Transfer</h4>\n<!-- /wp:heading --><!-- wp:cover {\"url\":\"https://eyeshottourism.com/wp-content/uploads/2025/11/1764154724420.png\",\"id\":151,\"dimRatio\":50,\"align\":\"full\"} -->\n<img src=\"https://eyeshottourism.com/wp-content/uploads/2025/11/1764154724420.png\" alt=\"\" data-object-fit=\"cover\" />\n<!-- wp:paragraph {\"placeholder\":\"Content…\"} -->\n<p>Arrive in Qatar with seamless, private SUV transfers directly to your booked luxury accommodation.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:cover -->\n<!-- /wp:group -->\n<!-- /wp:column --><!-- wp:column -->\n<!-- wp:group {\"style\":{\"dimensions\":{\"minHeight\":\"100%\"},\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":\"4px\"}},\"backgroundColor\":\"tertiary\",\"layout\":{\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"24px\"}},\"typography\":{\"fontSize\":\"20px\",\"lineHeight\":\"1.5\"},\"color\":{\"text\":\"#666161\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#666161\"}}}}} -->\n<h4 style=\"color: #666161; margin-top: 24px; font-size: 20px; line-height: 1.5;\">Bespoke Accommodation</h4>\n<!-- /wp:heading --><!-- wp:cover {\"url\":\"https://eyeshottourism.com/wp-content/uploads/2025/11/1764155257454.png\",\"id\":152,\"dimRatio\":50,\"align\":\"full\"} -->\n<img src=\"https://eyeshottourism.com/wp-content/uploads/2025/11/1764155257454.png\" alt=\"\" data-object-fit=\"cover\" />\n<!-- wp:paragraph {\"placeholder\":\"Content…\"} -->\n<p>Effortlessly reserve hand-picked 5-star hotels and luxury desert glamping sites tailored to your personal taste</p>\n<!-- /wp:paragraph -->\n<!-- /wp:cover -->\n<!-- /wp:group -->\n<!-- /wp:column --><!-- wp:column -->\n<!-- wp:group {\"style\":{\"dimensions\":{\"minHeight\":\"100%\"},\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":\"4px\"}},\"backgroundColor\":\"tertiary\",\"layout\":{\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"24px\"}},\"typography\":{\"fontSize\":\"20px\",\"lineHeight\":\"1.5\"},\"color\":{\"text\":\"#666161\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#666161\"}}}}} -->\n<h4 style=\"color: #666161; margin-top: 24px; font-size: 20px; line-height: 1.5;\">VIP Event Access</h4>\n<!-- /wp:heading --><!-- wp:cover {\"url\":\"https://eyeshottourism.com/wp-content/uploads/2025/11/1764155719875.png\",\"id\":153,\"dimRatio\":50,\"align\":\"full\"} -->\n<img src=\"https://eyeshottourism.com/wp-content/uploads/2025/11/1764155719875.png\" alt=\"\" data-object-fit=\"cover\" />\n<!-- wp:paragraph {\"placeholder\":\"Content…\"} -->\n<p>Secure your tickets and transport to major regional events, spots tournaments, and private cultural performances.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:cover -->\n<!-- /wp:group -->\n<!-- /wp:column -->\n<!-- /wp:columns --><!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|70\",\"left\":\"var:preset|spacing|30\"}}}} -->\n<!-- wp:column -->\n<!-- wp:group {\"style\":{\"dimensions\":{\"minHeight\":\"100%\"},\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":\"4px\"}},\"backgroundColor\":\"tertiary\",\"layout\":{\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"24px\"}},\"typography\":{\"fontSize\":\"20px\",\"lineHeight\":\"1.5\"},\"color\":{\"text\":\"#666161\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#666161\"}}}}} -->\n<h4 style=\"color: #666161; margin-top: 24px; font-size: 20px; line-height: 1.5;\">24/7 Personal Concierge</h4>\n<!-- /wp:heading --><!-- wp:cover {\"url\":\"https://eyeshottourism.com/wp-content/uploads/2025/11/1764158956193.png\",\"id\":165,\"dimRatio\":50,\"customOverlayColor\":\"#73625b\",\"isUserOverlayColor\":false,\"sizeSlug\":\"full\",\"align\":\"full\"} -->\n<img src=\"https://eyeshottourism.com/wp-content/uploads/2025/11/1764158956193.png\" alt=\"\" data-object-fit=\"cover\" />\n<!-- wp:paragraph {\"placeholder\":\"Content…\"} -->\n<p>Dedicated on-call support for all your needs, ensuring a stress-free and truly personalized experience throughout your stay.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:cover -->\n<!-- /wp:group -->\n<!-- /wp:column --><!-- wp:column -->\n<!-- wp:group {\"style\":{\"dimensions\":{\"minHeight\":\"100%\"},\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":\"4px\"}},\"backgroundColor\":\"tertiary\",\"layout\":{\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"24px\"}},\"typography\":{\"fontSize\":\"20px\",\"lineHeight\":\"1.5\"},\"color\":{\"text\":\"#666161\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#666161\"}}}}} -->\n<h4 style=\"color: #666161; margin-top: 24px; font-size: 20px; line-height: 1.5;\">Aquatic &amp; Coastal Escapes</h4>\n<!-- /wp:heading --><!-- wp:cover {\"url\":\"https://eyeshottourism.com/wp-content/uploads/2025/11/1764160139056.png\",\"id\":167,\"dimRatio\":50,\"customOverlayColor\":\"#a78e80\",\"isUserOverlayColor\":false,\"isDark\":false,\"sizeSlug\":\"full\",\"align\":\"full\"} -->\n<img src=\"https://eyeshottourism.com/wp-content/uploads/2025/11/1764160139056.png\" alt=\"\" data-object-fit=\"cover\" />\n<!-- wp:paragraph {\"placeholder\":\"Content…\",\"style\":{\"color\":{\"text\":\"#ffffff\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#ffffff\"}}}}} -->\n<p style=\"color: #ffffff;\">Explore the stunning Arabian Gulf with private boat charters, paddle boarding, and coastal excursions guided by experts.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:cover -->\n<!-- /wp:group -->\n<!-- /wp:column --><!-- wp:column -->\n<!-- wp:group {\"style\":{\"dimensions\":{\"minHeight\":\"100%\"},\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":\"4px\"}},\"backgroundColor\":\"tertiary\",\"layout\":{\"type\":\"constrained\"}} -->\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"24px\"}},\"typography\":{\"fontSize\":\"20px\",\"lineHeight\":\"1.5\"},\"color\":{\"text\":\"#666161\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#666161\"}}}}} -->\n<h4 style=\"color: #666161; margin-top: 24px; font-size: 20px; line-height: 1.5;\">Fine Dining &amp; Retail Passages</h4>\n<!-- /wp:heading --><!-- wp:cover {\"url\":\"https://eyeshottourism.com/wp-content/uploads/2025/11/1764160579883-1024x639.png\",\"id\":169,\"dimRatio\":50,\"customOverlayColor\":\"#9e9289\",\"isUserOverlayColor\":false,\"isDark\":false,\"sizeSlug\":\"large\",\"align\":\"full\"} -->\n<img src=\"https://eyeshottourism.com/wp-content/uploads/2025/11/1764160579883-1024x639.png\" alt=\"\" data-object-fit=\"cover\" />\n<!-- wp