(403, 1, '2026-01-01 11:24:05', '0000-00-00 00:00:00', '<!-- wp:group {\"metadata\":{\"name\":\"Section\"},\"align\":\"full\",\"className\":\"is-style-ext-preset\\u002d\\u002dgroup\\u002d\\u002dnatural-1\\u002d\\u002dsection\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|70\",\"bottom\":\"var:preset|spacing|70\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"blockGap\":\"var:preset|spacing|55\"}},\"backgroundColor\":\"background\",\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull is-style-ext-preset--group--natural-1--section has-background-background-color has-background\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--70);padding-bottom:var(--wp--preset--spacing--70)\"><!-- wp:group {\"metadata\":{\"name\":\"Section Header\"},\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|30\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group alignwide\"><!-- wp:group {\"metadata\":{\"name\":\"Section Intro\"},\"style\":{\"spacing\":{\"blockGap\":\"1.5rem\"}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Discover Exceptional Tour Packages, Daily Tour Services and Hourly Transit or Layover Tours.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Explore key insights and distinctive benefits that make your journey with Eyeshot Tourism truly unforgettable.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|40\",\"left\":\"var:preset|spacing|40\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"verticalAlignment\":\"stretch\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|30\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-stretch\"><!-- wp:group {\"metadata\":{\"name\":\"Card\",\"categories\":[\"card\"],\"patternName\":\"core/block/2379\"},\"className\":\"is-style-ext-preset\\u002d\\u002dgroup\\u002d\\u002dnatural-1\\u002d\\u002ditem-card-1\\u002d\\u002dalign-center\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group is-style-ext-preset--group--natural-1--item-card-1--align-center\"><!-- wp:group {\"metadata\":{\"name\":\"Content\"},\"className\":\"is-style-default\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group is-style-default\"><!-- wp:image {\"scale\":\"cover\",\"sizeSlug\":\"large\",\"align\":\"center\",\"className\":\"ext-aspect-landscape extendify-image-import\",\"style\":{\"color\":{\"duotone\":\"var:preset|duotone|primary-foreground\"}}} -->\n<figure class=\"wp-block-image aligncenter size-large ext-aspect-landscape extendify-image-import\"><img src=\"data:image/svg+xml;base64,\" alt=\"\" style=\"object-fit:cover\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3} -->\n<h3 class=\"wp-block-heading has-text-align-center\">Tour Packages</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Receive expert advice tailored to help you navigate Qatar’s culture and attractions with ease and confidence.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"stretch\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|30\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-stretch\"><!-- wp:group {\"metadata\":{\"name\":\"Card\",\"categories\":[\"card\"],\"patternName\":\"core/block/2379\"},\"className\":\"is-style-ext-preset\\u002d\\u002dgroup\\u002d\\u002dnatural-1\\u002d\\u002ditem-card-1\\u002d\\u002dalign-ce