(663, 1, '2026-02-04 07:47:57', '2026-02-04 07:47:57', '<!-- wp:group {\"metadata\":{\"name\":\"Hero Header\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"0\",\"left\":\"0\",\"top\":\"0px\",\"bottom\":\"0px\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"backgroundColor\":\"background\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-background-background-color has-background\" style=\"margin-top:0;margin-bottom:0;padding-top:0px;padding-right:0;padding-bottom:0px;padding-left:0\"><!-- wp:cover {\"url\":\"https://eyeshottourism.com/wp-content/uploads/2025/11/2025-11-26-08-50-50-8b3dd4b0-764d-4031-8d1f-323a586231f3-1.jpg\",\"id\":129,\"dimRatio\":60,\"overlayColor\":\"black\",\"isUserOverlayColor\":true,\"focalPoint\":{\"x\":0.55,\"y\":0.44},\"minHeight\":700,\"minHeightUnit\":\"px\",\"contentPosition\":\"center center\",\"sizeSlug\":\"full\",\"align\":\"full\",\"className\":\"extendify-image-import\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\"}}}} -->\n<div class=\"wp-block-cover alignfull extendify-image-import\" style=\"padding-right:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--30);min-height:700px\"><img class=\"wp-block-cover__image-background wp-image-129 size-full\" alt=\"\" src=\"https://eyeshottourism.com/wp-content/uploads/2025/11/2025-11-26-08-50-50-8b3dd4b0-764d-4031-8d1f-323a586231f3-1.jpg\" style=\"object-position:55% 44%\" data-object-fit=\"cover\" data-object-position=\"55% 44%\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-black-background-color has-background-dim-60 has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"8rem\",\"bottom\":\"8rem\",\"left\":\"0\",\"right\":\"0\"},\"margin\":{\"top\":\"-100px\",\"bottom\":\"20px\"},\"blockGap\":\"0\"},\"dimensions\":{\"minHeight\":\"0px\"}},\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"left\",\"wideSize\":\"\",\"contentSize\":\"\"}} -->\n<div class=\"wp-block-group\" style=\"min-height:0px;margin-top:-100px;margin-bottom:20px;padding-top:8rem;padding-right:0;padding-bottom:8rem;padding-left:0\"><!-- wp:heading {\"textAlign\":\"left\",\"level\":1,\"style\":{\"spacing\":{\"padding\":{\"top\":\"0.7rem\",\"bottom\":\"0.7rem\",\"left\":\"0\",\"right\":\"0\"}}},\"textColor\":\"white\"} -->\n<h1 class=\"wp-block-heading has-text-align-left has-white-color has-text-color\" style=\"padding-top:0.7rem;padding-right:0;padding-bottom:0.7rem;padding-left:0\">Personalized Journeys and Adventures Through Vibrant Qatar</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"13px\",\"top\":\"13px\"}}},\"textColor\":\"white\"} -->\n<p class=\"has-white-color has-text-color\" style=\"margin-top:13px;margin-bottom:13px\">Qatar Tourism: Discover immersive tours, desert safaris, aquatic excursions exclusive adventures that reveal Qatar\'s rich heritage, modern marvels, and hidden gems, crafted with meticulous attention to detail for an unforgettable experience.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"align\":\"full\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|20\",\"left\":\"var:preset|spacing|20\"},\"margin\":{\"top\":\"0\",\"bottom\":\"110px\"}}},\"layout\":{\"type\":\"flex\",\"orientation\":\"horizontal\"}} -->\n<div class=\"wp-block-buttons alignfull\" style=\"margin-top:0;margin-bottom:110px\"><!-- wp:button {\"className\":\"is-style-ext-preset\\u002d\\u002dbutton\\u002d\\u002dsoft-1\\u002d\\u002dbutton-1\",\"style\":{\"color\":{\"background\":\"#fcfcfc\",\"text\":\"#111111\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#111111\"}}},\"spacing\":{\"padding\":{\"left\":\"var:preset|spacing|55\",\"right\":\"var:preset|spacing|55\"}}}} -->\n<div class=\"wp-block-button is-style-ext-preset--button--soft-1--button-1\"><a class=\"wp-block-button__link has-text-color has-background has-link-color wp-element-button\" href=\"https://eyeshottourism.com/shop/\" style=\"color:#111111;background-color:#fcfcfc;padding-right:var(--wp--preset--spacing--55);padding-left:var(--wp--preset--spacing--55)\">Discover Now</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n\n<!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\"},\"margin\":{\"top\":\"-100px\",\"bottom\":\"-100px\"}}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"wp-block-group alignwide\" style=\"margin-top:-100px;margin-bottom:-100px;padding-top:0;padding-bottom:0\"><!-- wp:jetpack/send-a-message -->\n<div class=\"wp-block-jetpack-send-a-message\"><!-- wp:jetpack/whatsapp-button {\"countryCode\":\"974QA\",\"phoneNumber\":\"66094911\",\"firstMessage\":\"Hi Eyeshot Tourism! I’m interested in booking a tour in Qatar. Could you provide more details on your current packages?\",\"openInNewTab\":true,\"align\":\"left\",\"className\":\"whatsapp-glow-effect\"} -->\n<div class=\"wp-block-jetpack-whatsapp-button alignleft whatsapp-glow-effect is-color-dark\"><a class=\"whatsapp-block__button\" href=\"https://api.whatsapp.com/send?phone=97466094911&amp;text=Hi%20Eyeshot%20Tourism!%20I%E2%80%99m%20interested%20in%20booking%20a%20tour%20in%20Qatar.%20Could%20you%20provide%20more%20details%20on%20your%20current%20packages%3F\" style=\"background-color:#25D366;color:#fff\" target=\"_blank\" rel=\"noopener noreferrer\">Chat with Eyeshot Tourism</a></div>\n<!-- /wp:jetpack/whatsapp-button --></div>\n<!-- /wp:jetpack/send-a-message --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"About Us\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\"},\"blockGap\":\"0\",\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"color\":{\"background\":\"#dddddd\"},\"dimensions\":{\"minHeight\":\"0px\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-background\" id=\"about\" style=\"background-color:#dddddd;min-height:0px;margin-top:0;margin-bottom:0;padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:cover {\"dimRatio\":0,\"customOverlayColor\":\"#dddddd\",\"isUserOverlayColor\":true,\"focalPoint\":{\"x\":0.58,\"y\":0.61},\"minHeight\":50.1,\"minHeightUnit\":\"vh\",\"contentPosition\":\"center center\",\"isDark\":false,\"metadata\":{\"categories\":[\"gallery\"],\"patternName\":\"core/fullscreen-cover-image-gallery\",\"name\":\"Fullscreen cover image gallery\"},\"align\":\"full\",\"className\":\"is-style-default\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"blockGap\":\"0\",\"padding\":{\"right\":\"0\",\"left\":\"0\",\"top\":\"var:preset|spacing|20\",\"bottom\":\"var:preset|spacing|20\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-cover alignfull is-light is-style-default\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--20);padding-right:0;padding-bottom:var(--wp--preset--spacing--20);padding-left:0;min-height:50.1vh\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-0 has-background-dim\" style=\"background-color:#dddddd\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:superblockslider/slider {\"slides\":[\"Title\",\"Title\",\"Title\",\"Title\"],\"transitionSpeedValue\":\".7s\",\"autoplayIntervalValue\":\"1.3s\",\"hoverPauseValue\":false,\"navigationColorValue\":\"#d4a72c\",\"sliderHeightValue\":\"75vh\",\"editorCurrentImageValue\":{\"imageWidth\":1024,\"imageHeight\":1536},\"align\":\"center\"} -->\n<div class=\"wp-block-superblockslider-slider aligncenter superblockslider\" style=\"height:75vh;width:100%\" data-transition-duration=\".7s\" data-animation=\"cubic-bezier(0.46, 0.03, 0.52, 0.96)\" data-transition-speed=