\":\"4px\"}},\"backgroundColor\":\"tertiary\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-tertiary-background-color has-background\" style=\"border-radius:4px;min-height:100%;padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"spacing\":{\"margin\":{\"top\":\"24px\"}},\"typography\":{\"fontSize\":\"20px\",\"lineHeight\":\"1.5\"},\"color\":{\"text\":\"#666161\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#666161\"}}}}} -->\n<h4 class=\"wp-block-heading has-text-align-center has-text-color has-link-color\" style=\"color:#666161;margin-top:24px;font-size:20px;line-height:1.5\">Premium Airport Transfer</h4>\n<!-- /wp:heading -->\n\n<!-- wp:cover {\"url\":\"https://eyeshottourism.com/wp-content/uploads/2025/11/1764154724420.png\",\"id\":151,\"dimRatio\":50,\"align\":\"full\"} -->\n<div class=\"wp-block-cover alignfull\"><img class=\"wp-block-cover__image-background wp-image-151\" alt=\"\" src=\"https://eyeshottourism.com/wp-content/uploads/2025/11/1764154724420.png\" data-object-fit=\"cover\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:paragraph {\"placeholder\":\"Content…\"} -->\n<p>Arrive in Qatar with seamless, private SUV transfers directly to your booked luxury accommodation.</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"style\":{\"dimensions\":{\"minHeight\":\"100%\"},\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":\"4px\"}},\"backgroundColor\":\"tertiary\",\"la