(486, 1, '2026-01-19 08:06:56', '2026-01-19 08:06:56', '\r\n// 1. Change the page title from \"Order received\" to \"Booking received\"\r\nadd_filter( \'woocommerce_endpoint_order-received_title\', \'eyeshot_change_thank_you_title\' );\r\nfunction eyeshot_change_thank_you_title( $old_title ) {\r\n    return \'Booking received\';\r\n}\r\n\r\n// 2. Add custom Qatar arrival instructions and a WhatsApp button\r\nadd_filter(\'woocommerce_thankyou_order_received_text\', \'eyeshot_custom_thankyou_text\', 10, 2 );\r\nfunction eyeshot_custom_thankyou_text( $str, $order ) {\r\n    $new_text = \'<p style=\"font-size:18px; color:#2c3e50;\"><strong>Welcome to Qatar!</strong> We have received your booking. Our team is now preparing your tour.</p>\';\r\n    $new_text .= \'<p>For immediate pickup coordination at the airport or hotel, please message us on WhatsApp:</p>\';\r\n    $new_text .= \'<a href=\"https://wa.me/97466094911\" style=\"background-color:#25D366; color:white; padding:12px 20px; text-decoration:none; border-radius:5px; font-weight:bold; display:inline-block;\">Chat with Eyeshot on WhatsApp</a>\';\r\n   \r\n    return $new_text;\r\n}', 'Eyeshot Booking Confirmation', '', 'publish', 'closed', 'closed', '', 'eyeshot-booking-confirmation', '', '', '2026-01-22 06:20:13', '2026-01-22 06:20:13', '', 0, 'https://eyeshottourism.com/wpcode/eyeshot-booking-confirmation/', 0, 'wpcode', '', 0),
(487, 1, '2026-01-19 08:57:02', '2026-01-19 08:57:02', '<!-- wp:template-part {\"slug\":\"header\",\"theme\":\"extendable\",\"tagName\":\"header\"} /-->\n\n<!-- wp:group {\"tagName\":\"main\",\"className\":\"is-style-ext-preset\\u002d\\u002dgroup\\u002d\\u002dnatural-1\\u002d\\u002dtemplate\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<main class=\"wp-block-group is-style-ext-preset--group--natural-1--template\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\"><!-- wp:heading {\"level\":1,\"align\":\"wide\"} -->\n<h1 class=\"wp-block-heading alignwide\">Booking Received</h1>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4,\"align\":\"wide\"} -->\n<h4 class=\"wp-block-heading alignwide\">Welcome to Qatar! We have received your Booking. Our team will contact you via WhatsApp shortly for your tour and pickup details.</h4>\n<!-- /wp:heading -->\n\n<!-- wp:jetpack/send-a-message -->\n<div class=\"wp-block-jetpack-send-a-message\"><!-- wp:jetpack/whatsapp-button {\"countryCode\":\"974QA\",\"phoneNumber\":\"66094911\",\"firstMessage\":\"Hi Eyeshot Tourism!\\nI just confirmed my booking on your website. Please let me know the next steps for my pickup and tour coordination.\\nSee you soon. \\nOrder Number / Name:    \",\"openInNewTab\":true,\"align\":\"center\"} -->\n<div class=\"wp-block-jetpack-whatsapp-button aligncenter is-color-dark\"><a class=\"whatsapp-block__button\" href=\"https://api.whatsapp.com/send?phone=97466094911&amp;text=Hi%20Eyeshot%20Tourism!%0AI%20just%20confirmed%20my%20booking%20on%20your%20website.%20Please%20let%20me%20know%20the%20next%20steps%20for%20my%20pickup%20and%20tour%20coordination.%0ASee%20you%20soon.%20%0AOrder%20Number%20%2F%20Name%3A%20%20%20%20\" style=\"background-color:#25D366;color:#fff\" target=\"_blank\" rel=\"noopener noreferrer\">Chat with Eyeshot Tourism on WhatsApp</a></div>\n<!-- /wp:jetpack/whatsapp-button --></div>\n<!-- /wp:jetpack/send-a-message -->\n\n<!-- wp:woocommerce/order-confirmation-summary {\"metadata\":{\"ignoredHookedBlocks\":[\"woocommerce/order-confirmation-create-account\"]}} /-->\n\n<!-- wp:woocommerce/order-confirmation-totals-wrapper {\"align\":\"wide\"} -->\n<!-- wp:heading {\"style\":{\"typography\":{\"fontSize\":\"24px\"}}} -->\n<h2 class=\"wp-block-heading\" style=\"font-size:24px\">The Blueprint of Your Doha Legacy</h2>\n<!-- /wp:heading -->\n\n<!-- wp:woocommerce/order-confirmation-totals {\"lock\":{\"remove\":true}} /-->\n<!-- /wp:woocommerce/order-confirmation-totals-wrapper -->\n\n<!-- wp:woocommerce/order-confirmation-downloads-wrapper {\"align\":\"wide\"} -->\n<!-- wp:heading {\"style\":{\"typography\":{\"fontSize\":\"24px\"}}} -->\n<h2 class=\"wp-block-heading\" style=\"font-size:24px\">Downloads</h2>\n<!-- /wp:heading -->\n\n<!-- wp:woocommerce/order-confirmation-downloads {\"lock\":{\"remove\":true}} /-->\n<!-- /wp:woocommerce/order-confirmation-downloads-wrapper -->\n\n<!-- wp:columns {\"align\":\"wide\",\"className\":\"wc-block-order-confirmation-address-wrapper\"} -->\n<div class=\"wp-block-columns alignwide wc-block-order-confirmation-address-wrapper\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:woocommerce/order-confirmation-shipping-wrapper {\"align\":\"wide\"} -->\n<!-- wp:heading {\"style\":{\"typography\":{\"fontSize\":\"24px\"}}} -->\n<h2 class=\"wp-block-heading\" style=\"font-size:24px\">Shipping address</h2>\n<!-- /wp:heading -->\n\n<!-- wp:woocommerce/order-confirmation-shipping-address {\"lock\":{\"remove\":true}} /-->\n<!-- /wp:woocommerce/order-confirmation-shipping-wrapper --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:woocommerce/order-confirmation-billing-wrapper {\"align\":\"wide\"} -->\n<!-- wp:heading {\"style\":{\"typography\":{\"fontSize\":\"24px\"}}} -->\n<h2 class=\"wp-block-heading\" style=\"font-size:24px\">Billing address</h2>\n<!-- /wp:heading -->\n\n<!-- wp:woocommerce/order-confirmation-billing-address {\"lock\":{\"remove\":true}} /-->\n<!-- /wp:woocommerce/order-confirmation-billing-wrapper --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:woocommerce/order-confirmation-additional-fields-wrapper {\"align\":\"wide\"} -->\n<!-- wp:heading {\"style\":{\"typography\":{\"fontSize\":\"24px\"}}} -->\n<h2 class=\"wp-block-heading\" style=\"font-size:24px\">\n		Additional information	</h2>\n<!-- /wp:heading -->\n\n<!-- wp:woocommerce/order-confirmation-additional-fields /-->\n<!-- /wp:woocommerce/order-confirmation-additional-fields-wrapper -->\n\n<!-- wp:woocommerce/order-confirmation-additional-information /--></main>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"theme\":\"extendable\",\"tagName\":\"footer\"} /-->', 'Order Confirmation', 'The Order Confirmation template serves as a receipt and confirmation of a successful purchase. It includes a summary of the ordered items, shipping, billing, and totals.', 'publish', 'closed', 'closed', '', 'order-confirmation', '', '', '2026-02-03 11:00:36', '2026-02-03 11:00:36', '', 0, 'https://eyeshottourism.com/order-confirmation/', 0, 'wp_template', '', 0);
