(518, 1, '2026-01-22 06:16:49', '0000-00-00 00:00:00', '/* Force all checkout columns and tables to 100% width */\r\n.woocommerce-checkout .col2-set, \r\n.woocommerce-checkout #order_review, \r\n.woocommerce-checkout #order_review_heading {\r\n    width: 100% !important;\r\n    float: none !important;\r\n}\r\n\r\n/* Ensure the order table matches the payment box width */\r\n.woocommerce-checkout-review-order-table {\r\n    width: 100% !important;\r\n    margin-left: 0 !important;\r\n    margin-right: 0 !important;\r\n}\r\n\r\n/* Align the payment methods container */\r\n#add_payment_method #payment, .woocommerce-cart #payment, .woocommerce-checkout #payment {\r\n    width: 100% !important;\r\n}', 'aligne checkout page width', '', 'draft', 'closed', 'closed', '', '', '', '', '2026-01-22 06:16:49', '0000-00-00 00:00:00', '', 0, 'https://eyeshottourism.com/?post_type=wpcode&p=518', 0, 'wpcode', '', 0);
