\\n\\n\\/* Makes the logos a consistent small size so they fit *\\/\\n.woocommerce-checkout .wc_payment_method label img {\\n    max-height: 24px !important;\\n    width: auto !important;\\n    margin: 0 !important;\\n}\\n\\n\\n\\/* Forces Google\\/Apple Pay to stay in one horizontal line *\\/\\n.woocommerce-checkout .wc_payment_method label {\\n    display: flex !important;\\n    flex-direction: row !important;\\n    align-items: center !important;\\n    flex-wrap: nowrap !important; \\/* Prevents jumping to next line *\\/\\n    white-space: nowrap !important; \\/* Forces text to stay on one line *\\/\\n}\\n\\n\\/* Adjusts the logo size and adds a small gap *\\/\\n.woocommerce-checkout .wc_payment_method label img {\\n    max-height: 18px !important; \\/* Slightly smaller to ensure fit *\\/\\n    width: auto !important;\\n    margin-left: 10px !important; \\/* Space between text and logo *\\/\\n    display: inline-block !important;\\n}\\n\\n\\/* Ensures the radio button (the circle) stays aligned too *\\/\\n.wc_payment_method input[type=\\\"radio\\\"] {\\n    margin-top: 0 !important;\\n}\\n\\n\\n\\/* Forces the payment row into a 3-column grid that cannot wrap *\\/\\n.woocommerce-checkout .wc_payment_method label {\\n    display: grid !important;\\n    grid-template-columns: auto 1fr auto !important; \\/* Circle | Text | Logo *\\/\\n    align-items: center !important;\\n    gap: 12px !important;\\n    width: 100% !important;\\n    white-space: nowrap !important;\\n}\\n\\n\\/* Fixes the Icon size so it is visible but fits *\\/\\n.woocommerce-checkout .wc_payment_method label img {\\n    max-height: 22px !important;\\n    width: auto !important;\\n    margin: 0 !important;\\n    display: block !important;\\n}\\n\\n\\/* Ensures the radio button circle is perfectly aligned *\\/\\n.wc_payment_method input[type=\\\"radio\\\"] {\\n    margin: 0 !important;\\n    padding: 0 !important;\\n}\",\"spacing\":{\"padding\":{\"top\":\"0\",\"right\":\"var:preset|spacing|30\",\"bottom\":\"0\",\"left\":\"var:preset|spacing|30\"},\"blockGap\":\"0\"},\"elements\":{\"heading\":{\"color\":{\"text\":\"var(--wp--preset--color--foreground)\"}}},\"color\":{\"text\":\"var(--wp--preset--color--foreground-alt)\"}},\"settings\":{\"custom\":{\"elements\":{\"button\":{\":hover\":{\"color\":{\"background\":\"var(--wp--preset--color--foreground)\",\"text\":\"var(--wp--preset--color--background)\"}},\":focus\":{\"color\":{\"background\":\"var(--wp--preset--color--primary)\",\"text\":\"var(--wp--preset--color--background)\"}},\"color\":{\"background\":\"var(--wp--preset--color--primary)\",\"text\":\"var(--wp--preset--color--background)\"}}}},\"color\":{\"duotone\":{\"theme\":[{\"colors\":[\"#212023\",\"#744F39\"],\"slug\":\"primary-and-secondary\",\"name\":\"Primary and secondary\"},{\"colors\":[\"#212023\",\"#F9F8F1\"],\"slug\":\"primary-and-tertiary\",\"name\":\"Primary and tertiary\"},{\"colors\":[\"#744F39\",\"#212023\"],\"slug\":\"secondary-and-primary\",\"name\":\"Secondary and primary\"},{\"colors\":[\"#582A2F\",\"#FBEBE1\"],\"slug\":\"foreground-and-background\",\"name\":\"Foreground and background\"},{\"colors\":[\"#212023\",\"#582A2F\"],\"slug\":\"primary-foreground\",\"name\":\"Primary and Foreground\"},{\"colors\":[\"#FBEBE1\",\"#F9F8F1\"],\"slug\":\"background-tertiary\",\"name\":\"Background and Background Alt\"}]},\"palette\":{\"theme\":[{\"slug\":\"background\",\"color\":\"#FBEBE1\",\"name\":\"Background\"},{\"slug\":\"foreground\",\"color\":\"#582A2F\",\"name\":\"Foreground\"},{\"slug\":\"primary\",\"color\":\"#212023\",\"name\":\"Primary\"},{\"slug\":\"secondary\",\"color\":\"#744F39\",\"name\":\"Secondary\"},{\"slug\":\"tertiary\",\"color\":\"#F9F8F1\",\"name\":\"Tertiary\"},{\"slug\":\"foreground-alt\",\"color\":\"#4C3B35\",\"name\":\"Foreground Alt\"}]}}},\"isGlobalStylesUserThemeJSON\":true,\"version\":3}', 'Custom Styles', '', 'inherit', 'closed', 'closed', '', '5-revision-v1', '', '', '2026-01-22 10:34:32', '2026-01-22 10:34:32', '', 5, 