mns are-vertically-aligned-center is-not-stacked-on-mobile\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"24px\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:24px\"><!-- wp:image {\"sizeSlug\":\"large\",\"className\":\"extendify-image-import\",\"style\":{\"color\":{\"duotone\":\"var:preset|duotone|primary-foreground\"}}} -->\n<figure class=\"wp-block-image size-large extendify-image-import\"><img src=\"data:image/svg+xml;base64,\" alt=\"\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"\",\"style\":{\"spacing\":{\"blockGap\":\"0\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\"}},\"fontSize\":\"medium\"} -->\n<p class=\"has-medium-font-size\" style=\"font-style:normal;font-weight:500\">+974-3115-0667</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {\"verticalAlignment\":\"center\",\"isStackedOnMobile\":false,\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"12px\"}}}} -->\n<div class=\"wp-block-columns are-vertically-aligned-center is-not-stacked-on-mobile\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"24px\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:24px\"><!-- wp:image {\"sizeSlug\":\"large\",\"className\":\"extendify-image-import\",\"style\":{\"color\":{\"duotone\":\"var:preset|duotone|primary-foreground\"}}} -->\n<figure class=\"wp-block-image size-large extendify-image-import\"><img src=\"data:image/svg+xml;base64,\" alt=\"\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"\",\"style\":{\"spacing\":{\"blockGap\":\"0\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSt